def get_current_gpu_usage():
    """Get the current GPU memory usage."""
    if cfg.gpu_mem and cfg.device != 'cpu' and torch.cuda.is_available():
        result = subprocess.check_output([
            'nvidia-smi', '--query-compute-apps=pid,used_memory',
            '--format=csv,nounits,noheader'
        ], encoding='utf-8')
        current_pid = os.getpid()
        used_memory = 0
        for line in result.strip().split('\n'):
            line = line.split(', ')
            if current_pid == int(line[0]):
                used_memory += int(line[1])
        return used_memory
    else:
        return -1

def processes_point_clouds(cls: str) -> bool:
    cls = importlib.import_module('torch_geometric.nn.conv').__dict__[cls]
    signature = inspect.signature(cls.forward)
    return (('edge_index' not in str(signature)
             and 'csc' not in str(signature)) or 'pos' in str(signature))

def __getitem__(self, index: Union[Tensor, Any]) -> 'NodeSamplerInput':
    if not isinstance(index, Tensor):
        index = torch.tensor(index, dtype=torch.long)

    return NodeSamplerInput(
        self.input_id[index] if self.input_id is not None else index,
        self.node[index],
        self.time[index] if self.time is not None else None,
        self.input_type,

def forward(self, data: Data) -> Data:
    assert data.pos is not None
    device = data.pos.device

    if data.pos.size(0) < 2:
        data.edge_index = torch.empty(2, 0, dtype=torch.long,
                                      device=device)
    elif data.pos.size(0) == 2:
        data.edge_index = torch.tensor([[0, 1], [1, 0]], device=device)
    elif data.pos.size(0) == 3:
        data.face = torch.tensor([[0], [1], [2]], device=device)
    else:
        data = self._transform.forward(data)

    return data

def torch_load(path: str, map_location: Any = None) -> Any:
    if torch_geometric.typing.WITH_PT24:
        try:
            with fsspec.open(path, 'rb') as f:
                return torch.load(f, map_location, weights_only=True)
        except pickle.UnpicklingError as e:
            error_msg = str(e)
            if "add_safe_globals" in error_msg:
                warn_msg = ("Weights only load failed. Please file an issue "
                            "to make `torch.load(weights_only=True)` "
                            "compatible in your case.")
                match = re.search(r'add_safe_globals\(.*?\)', error_msg)
                if match is not None:
                    warnings.warn(
                        f"{warn_msg} Please use "
                        f"`torch.serialization.{match.group()}` to "
                        f"allowlist this global.", stacklevel=2)
                else:
                    warnings.warn(warn_msg, stacklevel=2)

                with fsspec.open(path, 'rb') as f:
                    return torch.load(f, map_location, weights_only=False)
            else:
                raise e

    with fsspec.open(path, 'rb') as f:
        return torch.load(f, map_location)

def _initialize_edge_mask(self, edge_mask_type, edge_type, E, N, device):
    """Initialize edge mask for a specific edge type."""
    if edge_mask_type is None:
        self.edge_mask[edge_type] = None
        self.hard_edge_mask[edge_type] = None
    elif edge_mask_type == MaskType.object:
        std = torch.nn.init.calculate_gain('relu') * sqrt(2.0 / (2 * N))
        self.edge_mask[edge_type] = Parameter(
            torch.randn(E, device=device) * std)
        self.hard_edge_mask[edge_type] = None
    else:
        raise ValueError(f"Invalid edge mask type: {edge_mask_type}")

def forward(self, x: Tensor, index: Optional[Tensor] = None,
            ptr: Optional[Tensor] = None, dim_size: Optional[int] = None,
            dim: int = -2) -> Tensor:

    if self.local_mlp is not None:
        x = self.local_mlp(x, batch=index, batch_size=dim_size)
    if self.local_nn is not None:
        x = self.local_nn(x)

    x = self.reduce(x, index, ptr, dim_size, dim, reduce='sum')

    if self.global_mlp is not None:
        x = self.global_mlp(x, batch=index, batch_size=dim_size)
    elif self.global_nn is not None:
        x = self.global_nn(x)

    return x

