def reset_parameters(self):
    super().reset_parameters()
    if not isinstance(self.g, torch.nn.UninitializedParameter):
        glorot(self.g)
        glorot(self.mu)
        glorot(self.sigma)
    if self.root_weight:
        self.root.reset_parameters()
    zeros(self.bias)

def get_edge_features_iter(
    self,
    feature_name: str = EDGE_PID,
    pids: Optional[KnowledgeGraphLike] = None,
    index_only: bool = False,
) -> Iterator[Any]:
    """Iterator version of get_edge_features. If index_only is True,
    yields indices instead of values.
    """
    if pids is None:
        pids = self.edge_attr[EDGE_PID]

    if feature_name in self._mapped_edge_features:
        feature_map_info = self.edge_attr[feature_name]
        from_feature_name, to_feature_vals = (
            feature_map_info.name,
            feature_map_info.values,
        )
        from_feature_vals = self.get_unique_edge_features(
            from_feature_name)
        feature_mapping = {k: i for i, k in enumerate(from_feature_vals)}

        for pid in pids:
            idx = self._edges[pid]
            from_feature_val = self.edge_attr[from_feature_name][idx]
            to_feature_idx = feature_mapping[from_feature_val]
            if index_only:
                yield to_feature_idx
            else:
                yield to_feature_vals[to_feature_idx]
    else:
        for pid in pids:
            idx = self._edges[pid]
            if index_only:
                yield idx
            else:
                yield self.edge_attr[feature_name][idx]

def validate_hop_context_time_ranges(
    pair: Dict[str, Any],
    local_ranges: List[Dict[str, Any]],
    cross_ranges: List[Dict[str, Any]],
) -> None:
    """Ensure hop contexts fall within known timestamp ranges. Adjust to the
    closest available match when possible and record validation warnings.
    """
    hop_contexts = pair.get('hop_contexts') or []
    if not hop_contexts:
        return

    warnings: List[str] = []
    for hop_entry in hop_contexts:
        start_ts = hop_entry.get('start_time')
        end_ts = hop_entry.get('end_time')
        try:
            start_seconds = parse_timestamp(start_ts) if start_ts else None
            end_seconds = parse_timestamp(end_ts) if end_ts else None
        except Exception:
            start_seconds = end_seconds = None

        target_range: Optional[Dict[str, Any]] = None
        if start_seconds is not None and end_seconds is not None:
            for candidate in local_ranges:
                if _range_contains(start_seconds, end_seconds, candidate):
                    target_range = candidate.copy()
                    target_range['source'] = candidate.get('source', 'local')
                    break
            if not target_range:
                for candidate in cross_ranges:
                    if _range_contains(start_seconds, end_seconds, candidate):
                        target_range = candidate.copy()
                        target_range['source'] = candidate.get(
                            'source', 'cross')
                        break

        if target_range:
            hop_entry['source'] = target_range.get('source')
            continue

        # Attempt to align with closest known range
        candidates = local_ranges + cross_ranges
        if start_seconds is not None and candidates:
            best_match = _find_best_matching_range(start_seconds, candidates)
        else:
            best_match = None

        if best_match and best_match.get('start') and best_match.get('end'):
            hop_entry['start_time'] = best_match['start']
            hop_entry['end_time'] = best_match['end']
            hop_entry['source'] = best_match.get('source')
            warnings.append(
                f'Hop {hop_entry.get("hop")} timestamps adjusted \
                    to nearest available range '
                f'({best_match.get("start")} - {best_match.get("end")}).')
        else:
            warnings.append(f'Hop {hop_entry.get("hop")} timestamps \
                    ({start_ts} - {end_ts}) do not map to known segments.')

    if warnings:
        pair.setdefault('validation_warnings', []).extend(warnings)

def write_epoch(self, cur_epoch):
    basic_stats = self.basic()

    # Try to load customized metrics
    task_stats = {}
    for custom_metric in cfg.custom_metrics:
        func = register.metric_dict.get(custom_metric)
        if not func:
            raise ValueError(
                f'Unknown custom metric function name: {custom_metric}')
        custom_metric_score = func(self._true, self._pred, self.task_type)
        task_stats[custom_metric] = custom_metric_score

    if not task_stats:  # use default metrics if no matching custom metric
        if self.task_type == 'regression':
            task_stats = self.regression()
        elif self.task_type == 'classification_binary':
            task_stats = self.classification_binary()
        elif self.task_type == 'classification_multi':
            task_stats = self.classification_multi()
        else:
            raise ValueError('Task has to be regression or classification')

    epoch_stats = {'epoch': cur_epoch}
    eta_stats = {'eta': round(self.eta(cur_epoch), cfg.round)}
    custom_stats = self.custom()

    if self.name == 'train':
        stats = {
            **epoch_stats,
            **eta_stats,
            **basic_stats,
            **task_stats,
            **custom_stats
        }
    else:
        stats = {
            **epoch_stats,
            **basic_stats,
            **task_stats,
            **custom_stats
        }

    # print
    logging.info(f'{self.name}: {stats}')
    # json
    dict_to_json(stats, f'{self.out_dir}/stats.json')
    # tensorboard
    if cfg.tensorboard_each_run:
        dict_to_tb(stats, self.tb_writer, cur_epoch)
    self.reset()

def _fn_apply(self, args, fn, fn_inverse):
    if not self.disable:
        out = InvertibleFunction.apply(
            fn,
            fn_inverse,
            self.num_bwd_passes,
            len(args),
            *args,
            *tuple(p for p in self.parameters() if p.requires_grad),
        )
    else:
        out = fn(*args)

    # If the layer only has one input, we unpack the tuple:
    if isinstance(out, tuple) and len(out) == 1:
        return out[0]

    return out

def lists_distance(l1, l2):
    assert len(l1) == len(l2)
    dist = 0
    for i in range(len(l1)):
        if l1[i] != l2[i]:
            dist += 1
    return dist

def message_and_aggregate(
    self,
    edge_index: Adj,
    x: OptPairTensor,
    edge_weight: OptTensor,
) -> Tensor:

    if not torch.jit.is_scripting() and isinstance(edge_index, EdgeIndex):
        return edge_index.matmul(
            other=x[0],
            input_value=edge_weight,
            reduce=self.aggr,
            transpose=True,
        )

    return spmm(edge_index, x[0], reduce=self.aggr)

def forward(self, batch):
    for layer in self.children():
        batch = layer(batch)
    if cfg.gnn.l2norm:
        batch.x = F.normalize(batch.x, p=2, dim=-1)
    return batch

def run_inference(dataset, model, epochs, profiling, bf16, use_compile,
                  permute_masks=None, logger=None):
    data = dataset[0]
    if permute_masks is not None:
        data = permute_masks(data, dataset.num_classes)
    data = data.to(device)

    model.to(device).reset_parameters()
    if use_compile:
        model = torch.compile(model)

    if torch.cuda.is_available():
        amp = torch.amp.autocast('cuda', enabled=False)
    else:
        amp = torch.cpu.amp.autocast(enabled=bf16)
    if bf16:
        data.x = data.x.to(torch.bfloat16)

    with amp:
        for epoch in range(1, epochs + 1):
            if epoch == epochs:
                with timeit():
                    inference(model, data)
            else:
                inference(model, data)

        if profiling:
            with torch_profile():
                inference(model, data)

