def size(
    self, dim: Optional[int] = None
) -> Union[Tuple[Optional[int], Optional[int]], Optional[int]]:

    if self._key is None:
        raise NameError("Unable to infer 'size' without explicit "
                        "'_key' assignment")

    size = (self._parent()[self._key[0]].num_nodes,
            self._parent()[self._key[-1]].num_nodes)

    return size if dim is None else size[dim]

def _calculate_base_loss(self, y_hat: Tensor, y: Tensor) -> Tensor:
    """Calculate base loss based on model configuration."""
    if self.model_config.mode == ModelMode.binary_classification:
        return self._loss_binary_classification(y_hat, y)
    elif self.model_config.mode == ModelMode.multiclass_classification:
        return self._loss_multiclass_classification(y_hat, y)
    elif self.model_config.mode == ModelMode.regression:
        return self._loss_regression(y_hat, y)
    else:
        raise ValueError(
            f"Unsupported model mode: {self.model_config.mode}")

def process(self) -> None:
    raw_dir = self.raw_dir
    filenames = fs.ls(self.raw_dir)
    if len(filenames) == 1 and fs.isdir(filenames[0]):
        raw_dir = filenames[0]

    raw_files = fs.ls(raw_dir)

    data_list: Union[List[Data], List[EgoData]]
    if self.name[:4] == 'ego-':
        data_list = read_ego(raw_files, self.name[4:])
    elif self.name[:4] == 'soc-':
        data_list = read_soc(raw_files, self.name[:4])
    elif self.name[:5] == 'wiki-':
        data_list = read_wiki(raw_files, self.name[5:])
    else:
        raise NotImplementedError

    if len(data_list) > 1 and self.pre_filter is not None:
        data_list = [data for data in data_list if self.pre_filter(data)]

    if self.pre_transform is not None:
        data_list = [self.pre_transform(data) for data in data_list]

    self.save(data_list, self.processed_paths[0])

def resolve(query: Any, *args: Any, **kwargs: Any) -> 'MotifGenerator':
    import torch_geometric.datasets.motif_generator as _motif_generators
    motif_generators = [
        gen for gen in vars(_motif_generators).values()
        if isinstance(gen, type) and issubclass(gen, MotifGenerator)
    ]
    return resolver(motif_generators, {}, query, MotifGenerator, 'Motif',
                    *args, **kwargs)

def process(self) -> None:
    with open(self.raw_paths[1]) as f:
        manifest = json.load(f)
    total = manifest['full_train'] + manifest['full_test']
    partial = set(manifest[f'{self.task}_{self.split}'])

    data_list = []
    raw_data = fs.torch_load(self.raw_paths[0])
    for k, s in enumerate(total):
        if s in partial:
            data = Data(**raw_data[k])

            if self.pre_filter is not None and not self.pre_filter(data):
                continue
            if self.pre_transform is not None:
                data = self.pre_transform(data)

            data_list.append(data)

    self.save(data_list, self.processed_paths[0])

def reset_parameters(self):
    r"""Resets all learnable parameters of the module."""
    for conv in self.convs:
        conv.reset_parameters()
    for norm in self.norms:
        if hasattr(norm, 'reset_parameters'):
            norm.reset_parameters()
    if hasattr(self, 'jk'):
        self.jk.reset_parameters()
    if hasattr(self, 'lin'):
        self.lin.reset_parameters()

