def slice_to_range(self, indices: slice) -> range:
    start = 0 if indices.start is None else indices.start
    stop = len(self) if indices.stop is None else indices.stop
    step = 1 if indices.step is None else indices.step

    return range(start, stop, step)

def get_csr(self) -> Tuple[Tuple[Tensor, Tensor], Optional[Tensor]]:
    r"""Returns the compressed CSR representation
    :obj:`(rowptr, col), perm` in case :class:`EdgeIndex` is sorted.
    """
    if self.is_sorted_by_row:
        return (self.get_indptr(), self._data[1]), None

    assert self.is_sorted_by_col
    (row, col), perm = self._sort_by_transpose()

    if self._T_indptr is not None:
        rowptr = self._T_indptr
    elif self.is_undirected and self._indptr is not None:
        rowptr = self._indptr
    else:
        rowptr = self._T_indptr = index2ptr(row, self.get_num_rows())

    return (rowptr, col), perm

def collate_fn(self, index):
    if not isinstance(index, Tensor):
        index = torch.tensor(index)

    if isinstance(self.data, Data):
        return self.data.subgraph(index)

    elif isinstance(self.data, HeteroData):
        node_dict = {
            key: index[(index >= start) & (index < end)] - start
            for key, (start, end) in self.node_dict.items()
        }
        return self.data.subgraph(node_dict)

def _select(input: EdgeIndex, dim: int, index: int) -> Union[Tensor, Index]:
    out = aten.select.int(input._data, dim, index)

    if dim == 0 or dim == -2:
        out = Index(out)

        if index == 0 or index == -2:  # Row-select:
            out._dim_size = input.sparse_size(0)
            out._is_sorted = input.is_sorted_by_row
            if input.is_sorted_by_row:
                out._indptr = input._indptr

        else:  # Col-select:
            assert index == 1 or index == -1
            out._dim_size = input.sparse_size(1)
            out._is_sorted = input.is_sorted_by_col
            if input.is_sorted_by_col:
                out._indptr = input._indptr

    return out

def forward(
    self,
    x: Union[Tensor, Dict[NodeType, Tensor]],
    edge_index: Union[Tensor, Dict[EdgeType, Tensor]],
    node_type: OptTensor = None,
    edge_type: OptTensor = None,
    **kwargs,
) -> Union[Tensor, Dict[NodeType, Tensor]]:

    if isinstance(x, dict) and isinstance(edge_index, dict):
        return self.dict_forward(x, edge_index, **kwargs)

    elif (isinstance(x, Tensor) and isinstance(edge_index, Tensor)
          and node_type is not None and edge_type is not None):

        if len(kwargs) > 0:
            raise ValueError("Additional forward arguments not yet "
                             "supported in fused mode")

        return self.fused_forward(x, edge_index, node_type, edge_type)

    raise ValueError(f"Encountered invalid forward types in "
                     f"'{self.__class__.__name__}'")

