def get_bit(self, n):
    if self._value < 0:
        raise ValueError("no bit representation for negative values")
    try:
        try:
            result = (self._value >> n._value) & 1
            if n._value < 0:
                raise ValueError("negative bit count")
        except AttributeError:
            result = (self._value >> n) & 1
            if n < 0:
                raise ValueError("negative bit count")
    except OverflowError:
        result = 0
    return bool(result)

