def import_private_key(self, key_hex, kem_id):
    key_bin = unhexlify(key_hex)
    if kem_id == 0x0010:
        return ECC.construct(curve='p256', d=int.from_bytes(key_bin,
                                                            byteorder="big"))
    elif kem_id == 0x0011:
        return ECC.construct(curve='p384', d=int.from_bytes(key_bin,
                                                            byteorder="big"))
    elif kem_id == 0x0012:
        return ECC.construct(curve='p521', d=int.from_bytes(key_bin,
                                                            byteorder="big"))
    elif kem_id == 0x0020:
        return DH.import_x25519_private_key(key_bin)
    elif kem_id == 0x0021:
        return DH.import_x448_private_key(key_bin)

def size_in_bits(self):

    if self._value < 0:
        raise ValueError("Conversion only valid for non-negative numbers")

    if self._value == 0:
        return 1

    return self._value.bit_length()

def __init__(self, data, truncate):
    self._truncate = truncate

    if truncate is None:
        self.oid = "2.16.840.1.101.3.4.2.3"
        self.digest_size = 64
    elif truncate == "224":
        self.oid = "2.16.840.1.101.3.4.2.5"
        self.digest_size = 28
    elif truncate == "256":
        self.oid = "2.16.840.1.101.3.4.2.6"
        self.digest_size = 32
    else:
        raise ValueError("Incorrect truncation length. It must be '224' or '256'.")

    state = VoidPointer()
    result = _raw_sha512_lib.SHA512_init(state.address_of(),
                                         c_size_t(self.digest_size))
    if result:
        raise ValueError("Error %d while instantiating SHA-512"
                         % result)
    self._state = SmartPointer(state.get(),
                               _raw_sha512_lib.SHA512_destroy)
    if data:
        self.update(data)

def generate_cipher(self, module, key_size, params):
    params_dict = {}
    if params:
        params_dict = dict([x.split("=") for x in params.split(" ")])

    gen_tuple = []
    gen_dict = {}

    # 1st parameter (mandatory): key
    if params_dict.get('ks') == "x2":
        key = rng(2 * key_size)
    else:
        key = rng(key_size)
    gen_tuple.append(key)

    # 2nd parameter: mode
    mode = params_dict.get("mode")
    if mode:
        mode_value = getattr(module, mode, None)
        if mode_value is None:
            # Mode not available for this cipher
            raise ModeNotAvailable()
        gen_tuple.append(getattr(module, mode))

    # 3rd parameter: IV/nonce
    iv_length = params_dict.get("iv")
    if iv_length is None:
        iv_length = params_dict.get("nonce")
    if iv_length:
        if iv_length == "bs":
            iv_length = module.block_size
        iv = rng(int(iv_length))
        gen_tuple.append(iv)

    # Specific to CTR mode
    le = params_dict.get("little_endian")
    if le:
        if le == "True":
            le = True
        else:
            le = False

        # Remove iv from parameters
        gen_tuple = gen_tuple[:-1]
        ctr = Crypto.Util.Counter.new(module.block_size*8,
                                      initial_value=bytes_to_long(iv),
                                      little_endian=le,
                                      allow_wraparound=True)
        gen_dict['counter'] = ctr

    # Generate cipher
    return module.new(*gen_tuple, **gen_dict)

def test_mix(self):

    p1 = ECC.generate(curve='P-256').pointQ
    p2 = ECC.generate(curve='P-384').pointQ

    try:
        p1 + p2
        assert(False)
    except ValueError as e:
        assert "not on the same curve" in str(e)

    try:
        p1 += p2
        assert(False)
    except ValueError as e:
        assert "not on the same curve" in str(e)

    class OtherKeyType:
        pass

    self.assertFalse(p1 == OtherKeyType())
    self.assertTrue(p1 != OtherKeyType())

