    if tv.valid:
        self.assertEqual(ct, tv.ct)
        self.assertEqual(tag, tv.tag)
        self.warn(tv)

def _import_rfc5915_der(encoded, passphrase, curve_oid=None):

    # See RFC5915 https://tools.ietf.org/html/rfc5915
    #
    # ECPrivateKey ::= SEQUENCE {
    #           version        INTEGER { ecPrivkeyVer1(1) } (ecPrivkeyVer1),
    #           privateKey     OCTET STRING,
    #           parameters [0] ECParameters {{ NamedCurve }} OPTIONAL,
    #           publicKey  [1] BIT STRING OPTIONAL
    #    }

    ec_private_key = DerSequence().decode(encoded, nr_elements=(2, 3, 4))
    if ec_private_key[0] != 1:
        raise ValueError("Incorrect ECC private key version")

    scalar_bytes = DerOctetString().decode(ec_private_key[1]).payload

    next_element = 2

    # Try to decode 'parameters'
    if next_element < len(ec_private_key):
        try:
            parameters = DerObjectId(explicit=0).decode(ec_private_key[next_element]).value
            if curve_oid is not None and parameters != curve_oid:
                raise ValueError("Curve mismatch")
            curve_oid = parameters
            next_element += 1
        except ValueError:
            pass

    if curve_oid is None:
        raise ValueError("No curve found")

    for curve_name, curve in _curves.items():
        if curve.oid == curve_oid:
            break
    else:
        raise UnsupportedEccFeature("Unsupported ECC curve (OID: %s)" % curve_oid)

    modulus_bytes = curve.p.size_in_bytes()
    if len(scalar_bytes) != modulus_bytes:
        raise ValueError("Private key is too small")

    # Try to decode 'publicKey'
    point_x = point_y = None
    if next_element < len(ec_private_key):
        try:
            public_key_enc = DerBitString(explicit=1).decode(ec_private_key[next_element]).value
            public_key = _import_public_der(public_key_enc, curve_oid=curve_oid)
            point_x = public_key.pointQ.x
            point_y = public_key.pointQ.y
            next_element += 1
        except ValueError:
            pass

    d = Integer.from_bytes(scalar_bytes)
    return construct(curve=curve_name, d=d, point_x=point_x, point_y=point_y)

def _get_cell_value(self, cell) -> Scalar | NaTType:
    from odf.namespaces import OFFICENS

    if str(cell) == "#N/A":
        return np.nan

    cell_type = cell.attributes.get((OFFICENS, "value-type"))
    if cell_type == "boolean":
        if str(cell) == "TRUE":
            return True
        return False
    if cell_type is None:
        return self.empty_value
    elif cell_type == "float":
        # GH5394
        cell_value = float(cell.attributes.get((OFFICENS, "value")))
        val = int(cell_value)
        if val == cell_value:
            return val
        return cell_value
    elif cell_type == "percentage":
        cell_value = cell.attributes.get((OFFICENS, "value"))
        return float(cell_value)
    elif cell_type == "string":
        return self._get_cell_string_value(cell)
    elif cell_type == "currency":
        cell_value = cell.attributes.get((OFFICENS, "value"))
        return float(cell_value)
    elif cell_type == "date":
        cell_value = cell.attributes.get((OFFICENS, "date-value"))
        return pd.Timestamp(cell_value)
    elif cell_type == "time":
        stamp = pd.Timestamp(str(cell))
        # cast needed here because Scalar doesn't include datetime.time
        return cast("Scalar", stamp.time())
    else:
        self.close()
        raise ValueError(f"Unrecognized type {cell_type}")

def _take_new_index(
    obj: DataFrame | Series,
    indexer: npt.NDArray[np.intp],
    new_index: Index,
) -> DataFrame | Series:
    if isinstance(obj, ABCSeries):
        new_values = algos.take_nd(obj._values, indexer)
        return obj._constructor(new_values, index=new_index, name=obj.name)
    elif isinstance(obj, ABCDataFrame):
        new_mgr = obj._mgr.reindex_indexer(new_axis=new_index, indexer=indexer, axis=1)
        return obj._constructor_from_mgr(new_mgr, axes=new_mgr.axes)
    else:
        raise ValueError("'obj' should be either a Series or a DataFrame")

def create_description(
    self,
    complib,
    complevel: int | None,
    fletcher32: bool,
    expectedrows: int | None,
) -> dict[str, Any]:
    """create the description of the table from the axes & values"""
    # provided expected rows if its passed
    if expectedrows is None:
        expectedrows = max(self.nrows_expected, 10000)

    d = {"name": "table", "expectedrows": expectedrows}

    # description from the axes & values
    d["description"] = {a.cname: a.typ for a in self.axes}

    if complib:
        if complevel is None:
            complevel = self._complevel or 9
        filters = _tables().Filters(
            complevel=complevel,
            complib=complib,
            fletcher32=fletcher32 or self._fletcher32,
        )
        d["filters"] = filters
    elif self._filters is not None:
        d["filters"] = self._filters

    return d

def replace_regex(
    values: ArrayLike, rx: re.Pattern, value, mask: npt.NDArray[np.bool_] | None
) -> None:
    """
    Parameters
    ----------
    values : ArrayLike
        Object dtype.
    rx : re.Pattern
    value : Any
    mask : np.ndarray[bool], optional

    Notes
    -----
    Alters values in-place.
    """

    # deal with replacing values with objects (strings) that match but
    # whose replacement is not a string (numeric, nan, object)
    if isna(value) or not isinstance(value, str):

        def re_replacer(s):
            if is_re(rx) and isinstance(s, str):
                return value if rx.search(s) is not None else s
            else:
                return s

    else:
        # value is guaranteed to be a string here, s can be either a string
        # or null if it's null it gets returned
        def re_replacer(s):
            if is_re(rx) and isinstance(s, str):
                return rx.sub(value, s)
            else:
                return s

    f = np.vectorize(re_replacer, otypes=[np.object_])

    if mask is None:
        values[:] = f(values)
    else:
        if values.ndim != mask.ndim:
            mask = np.broadcast_to(mask, values.shape)
        values[mask] = f(values[mask])

def _select_font_family(self, font_names: Sequence[str]) -> int | None:
    family = None
    for name in font_names:
        family = self.FAMILY_MAP.get(name)
        if family:
            break

    return family

def get_sheet_data(
    self, sheet: CalamineSheet, file_rows_needed: int | None = None
) -> list[list[Scalar | NaTType | time]]:
    def _convert_cell(value: _CellValue) -> Scalar | NaTType | time:
        if isinstance(value, float):
            # GH#54564 - is_integer() returns False for NaN/Inf,
            # so this safely avoids int() on non-finite values
            if value.is_integer():
                return int(value)
            return value
        elif isinstance(value, (datetime, timedelta)):
            # Return as-is to match openpyxl behavior (GH#59186)
            return value
        elif isinstance(value, date):
            # Convert date to datetime to match openpyxl behavior (GH#59186)
            return datetime(value.year, value.month, value.day)
        elif isinstance(value, time):
            return value

        return value

    rows: list[list[_CellValue]] = sheet.to_python(
        skip_empty_area=False, nrows=file_rows_needed
    )
    data = [[_convert_cell(cell) for cell in row] for row in rows]

    return data

def _validate(self) -> None:
    super()._validate()

    # we allow rolling on a datetimelike index
    if (
        self.obj.empty
        or isinstance(self._on, (DatetimeIndex, TimedeltaIndex, PeriodIndex))
        or (isinstance(self._on.dtype, ArrowDtype) and self._on.dtype.kind in "mM")
    ) and isinstance(self.window, (str, BaseOffset, timedelta)):
        self._validate_datetimelike_monotonic()

        # this will raise ValueError on non-fixed freqs
        try:
            freq = to_offset(self.window)
        except (TypeError, ValueError) as err:
            raise ValueError(
                f"passed window {self.window} is not "
                "compatible with a datetimelike index"
            ) from err
        if isinstance(self._on, PeriodIndex):
            # error: Incompatible types in assignment (expression has type
            # "float", variable has type "Optional[int]")
            self._win_freq_i8 = freq.nanos / (  # type: ignore[assignment]
                self._on.freq.nanos / self._on.freq.n
            )
        else:
            try:
                unit = dtype_to_unit(self._on.dtype)  # type: ignore[arg-type]
            except TypeError:
                # if not a datetime dtype, eg for empty dataframes
                unit = "ns"
            unit = cast("TimeUnit", unit)
            self._win_freq_i8 = Timedelta(freq.nanos).as_unit(unit)._value

        # min_periods must be an integer
        if self.min_periods is None:
            self.min_periods = 1

        if self.step is not None:
            raise NotImplementedError(
                "step is not supported with frequency windows"
            )

    elif isinstance(self.window, BaseIndexer):
        # Passed BaseIndexer subclass should handle all other rolling kwargs
        pass
    elif not is_integer(self.window) or self.window < 0:
        raise ValueError("window must be an integer 0 or greater")

def _initialize_columns(
    self, cols: Iterable[Hashable] | None
) -> npt.NDArray[np.object_]:
    # validate mi options
    if self.has_mi_columns:
        if cols is not None:
            msg = "cannot specify cols with a MultiIndex on the columns"
            raise TypeError(msg)

    if cols is not None:
        if isinstance(cols, ABCIndex):
            cols = cols._get_values_for_csv(**self._number_format)
        else:
            cols = list(cols)
        self.obj = self.obj.loc[:, cols]

    # update columns to include possible multiplicity of dupes
    # and make sure cols is just a list of labels
    new_cols = self.obj.columns
    return new_cols._get_values_for_csv(**self._number_format)

def allows_duplicate_labels(self, value: bool) -> None:
    value = bool(value)
    obj = self._obj()
    if obj is None:
        raise ValueError("This flag's object has been deleted.")

    if not value:
        for ax in obj.axes:
            ax._maybe_check_unique()

    self._allows_duplicate_labels = value

def asfreq(
    obj: NDFrameT,
    freq,
    method=None,
    how=None,
    normalize: bool = False,
    fill_value=None,
) -> NDFrameT:
    """
    Utility frequency conversion method for Series/DataFrame.

    See :meth:`pandas.NDFrame.asfreq` for full documentation.
    """
    if isinstance(obj.index, PeriodIndex):
        if method is not None:
            raise NotImplementedError("'method' argument is not supported")

        if how is None:
            how = "E"

        if isinstance(freq, BaseOffset):
            if hasattr(freq, "_period_dtype_code"):
                freq = PeriodDtype(freq)._freqstr

        new_obj = obj.copy()
        new_obj.index = obj.index.asfreq(freq, how=how)

    elif len(obj.index) == 0:
        new_obj = obj.copy()

        new_obj.index = _asfreq_compat(obj.index, freq)
    else:
        unit: TimeUnit = "ns"
        if isinstance(obj.index, DatetimeIndex):
            # TODO: should we disallow non-DatetimeIndex?
            unit = obj.index.unit
        dti = date_range(obj.index.min(), obj.index.max(), freq=freq, unit=unit)
        dti.name = obj.index.name
        new_obj = obj.reindex(dti, method=method, fill_value=fill_value)
        if normalize:
            new_obj.index = new_obj.index.normalize()

    return new_obj

def agg(self) -> DataFrame | Series | None:
    """
    Provide an implementation for the aggregators.

    Returns
    -------
    Result of aggregation, or None if agg cannot be performed by
    this method.
    """
    func = self.func

    if isinstance(func, str):
        return self.apply_str()

    if is_dict_like(func):
        return self.agg_dict_like()
    elif is_list_like(func):
        # we require a list, but not a 'str'
        return self.agg_list_like()

    # caller can react
    return None

def _reduce(
    self,
    name: str,
    *,
    skipna: bool = True,
    keepdims: bool = False,
    axis: AxisInt | None = 0,
    **kwargs,
):
    nv.validate_minmax_axis(axis, self.ndim)
    if self.dtype.na_value is np.nan and name in ["any", "all"]:
        if not skipna:
            nas = pc.is_null(self._pa_array)
            arr = pc.or_kleene(nas, pc.not_equal(self._pa_array, ""))
        else:
            arr = pc.not_equal(self._pa_array, "")
        result = ArrowExtensionArray(arr)._reduce(
            name, skipna=skipna, keepdims=keepdims, **kwargs
        )
        if keepdims:
            # ArrowExtensionArray will return a length-1 bool[pyarrow] array
            return result.astype(np.bool_)
        return result

    if name in ("count", "min", "max", "sum", "argmin", "argmax"):
        result = self._reduce_calc(name, skipna=skipna, keepdims=keepdims, **kwargs)
    else:
        raise TypeError(f"Cannot perform reduction '{name}' with string dtype")

    if name in ("argmin", "argmax") and isinstance(result, pa.Array):
        return self._convert_int_result(result)
    elif isinstance(result, pa.Array):
        return type(self)(result, dtype=self.dtype)
    else:
        return result

def _not_in(x, y):
    """
    Compute the vectorized membership of ``x not in y`` if possible,
    otherwise use Python.
    """
    try:
        return ~x.isin(y)
    except AttributeError:
        if is_list_like(x):
            try:
                return ~y.isin(x)
            except AttributeError:
                pass
        return x not in y

def _unstack_frame(
    obj: DataFrame, level, fill_value=None, sort: bool = True
) -> DataFrame:
    assert isinstance(obj.index, MultiIndex)  # checked by caller
    unstacker = _Unstacker(
        obj.index, level=level, constructor=obj._constructor, sort=sort
    )

    if not obj._can_fast_transpose:
        mgr = obj._mgr.unstack(unstacker, fill_value=fill_value)
        return obj._constructor_from_mgr(mgr, axes=mgr.axes)
    else:
        return unstacker.get_result(
            obj, value_columns=obj.columns, fill_value=fill_value

def astype_is_view(dtype: DtypeObj, new_dtype: DtypeObj) -> bool:
    """Checks if astype avoided copying the data.

    Parameters
    ----------
    dtype : Original dtype
    new_dtype : target dtype

    Returns
    -------
    True if new data is a view or not guaranteed to be a copy, False otherwise
    """
    if dtype.kind in "iufb" and dtype.kind == new_dtype.kind:
        # fastpath for numeric dtypes
        if hasattr(dtype, "itemsize") and hasattr(new_dtype, "itemsize"):
            return dtype.itemsize == new_dtype.itemsize  # pyright: ignore[reportAttributeAccessIssue]

    if isinstance(dtype, np.dtype) and not isinstance(new_dtype, np.dtype):
        new_dtype, dtype = dtype, new_dtype

    if dtype == new_dtype:
        return True

    elif isinstance(dtype, np.dtype) and isinstance(new_dtype, np.dtype):
        # GH#63936: pandas realizes a numpy str ("<U") target as an object
        #  array via ensure_string_array, which views an object source.
        if is_object_dtype(dtype) and is_string_dtype(new_dtype):
            return True
        # Only equal numpy dtypes avoid a copy
        return False

    elif is_string_dtype(dtype) and is_string_dtype(new_dtype):
        from pandas.core.arrays.string_ import StringDtype

        if (
            isinstance(dtype, StringDtype)
            and dtype.storage == "pyarrow"
            and new_dtype == "object"
        ):
            # for conversion of pyarrow array to numpy object array -> always a copy
            return False
        # Potentially! a view when converting from object to string
        return True

    elif is_object_dtype(dtype) and new_dtype.kind == "O":
        # When the underlying array has dtype object, we don't have to make a copy
        return True

    elif dtype.kind in "mM" and new_dtype.kind in "mM":
        dtype = getattr(dtype, "numpy_dtype", dtype)
        new_dtype = getattr(new_dtype, "numpy_dtype", new_dtype)
        return getattr(dtype, "unit", None) == getattr(new_dtype, "unit", None)

    elif new_dtype == object and isinstance(
        dtype, (DatetimeTZDtype, PeriodDtype, IntervalDtype)
    ):
        return False

    elif isinstance(dtype, CategoricalDtype) and not isinstance(
        new_dtype, CategoricalDtype
    ):
        return False

    numpy_dtype = getattr(dtype, "numpy_dtype", None)
    new_numpy_dtype = getattr(new_dtype, "numpy_dtype", None)

    if numpy_dtype is None and isinstance(dtype, np.dtype):
        numpy_dtype = dtype

    if new_numpy_dtype is None and isinstance(new_dtype, np.dtype):
        new_numpy_dtype = new_dtype

    if numpy_dtype is not None and new_numpy_dtype is not None:
        # if both have NumPy dtype or one of them is a numpy dtype
        # they are only a view when the numpy dtypes are equal, e.g.
        # int64 -> Int64 or int64[pyarrow]
        # int64 -> Int32 copies
        return numpy_dtype == new_numpy_dtype

    # Assume this is a view since we don't know for sure if a copy was made
    return True

def astype_float_to_int_nansafe(
    values: np.ndarray, dtype: np.dtype, copy: bool
) -> np.ndarray:
    """
    astype with a check preventing converting NaN to a meaningless integer value.
    """
    if not np.isfinite(values).all():
        raise IntCastingNaNError(
            "Cannot convert non-finite values (NA or inf) to integer. "
            "Replace or remove non-finite values or cast to an integer type "
            "that supports these values (e.g. 'Int64')"
        )
    if dtype.kind == "u":
        # GH#45151
        if not (values >= 0).all():
            raise ValueError(f"Cannot losslessly cast from {values.dtype} to {dtype}")
    with warnings.catch_warnings():
        warnings.filterwarnings("ignore", category=RuntimeWarning)
        return values.astype(dtype, copy=copy)

def obj_to_write(self) -> NDFrame | Mapping[IndexLabel, Any]:
    if not self.index and self.orient == "split":
        return {"name": self.obj.name, "data": self.obj.values}
    else:
        return self.obj

def _from_sequence(cls, data, *, dtype=None, copy: bool = False) -> Self:
    if dtype:
        dtype = _validate_td64_dtype(dtype)

    data, copy = dtl.ensure_arraylike_for_datetimelike(
        data, copy, cls_name="TimedeltaArray"
    )

    unit = None
    if dtype is not None:
        if data.dtype == object:
            # GH#68639 the unit applies to the numeric entries, matching
            #  to_timedelta(data, unit=...), except that a str alongside
            #  them would make array_to_timedelta64 reject the unit
            apply_unit = not contains_str(data)
        else:
            apply_unit = data.dtype.kind in "iuf"
        if apply_unit:
            unit = np.datetime_data(dtype)[0]

    data = sequence_to_td64ns(data, copy=copy, unit=unit)

    if dtype is not None:
        data = astype_overflowsafe(data, dtype=dtype, copy=False)

    return cls._simple_new(data, dtype=data.dtype)

def _validate_color_args(self, color, colormap):
    if color is lib.no_default:
        # It was not provided by the user
        if "colors" in self.kwds and colormap is not None:
            warnings.warn(
                "'color' and 'colormap' cannot be used simultaneously. "
                "Using 'color'",
                stacklevel=find_stack_level(),
            )
        return None
    if self.nseries == 1 and color is not None and not is_list_like(color):
        # support series.plot(color='green')
        color = [color]

    if isinstance(color, tuple) and self.nseries == 1 and len(color) in (3, 4):
        # support RGB and RGBA tuples in series plot
        color = [color]

    if colormap is not None:
        warnings.warn(
            "'color' and 'colormap' cannot be used simultaneously. Using 'color'",
            stacklevel=find_stack_level(),
        )

    if self.style is not None:
        if isinstance(self.style, dict):
            styles = [self.style[col] for col in self.columns if col in self.style]  # type: ignore[union-attr]  # pyright: ignore[reportOptionalIterable]
        elif is_list_like(self.style):
            styles = self.style
        else:
            styles = [self.style]
        # need only a single match
        for s in styles:
            if _color_in_style(s):
                raise ValueError(
                    "Cannot pass 'style' string with a color symbol and "
                    "'color' keyword argument. Please use one or the "
                    "other or pass 'style' without a color symbol"
                )
    return color

def _border_style(
    self, style: str | None, width: str | None, color: str | None
) -> str | None:
    # convert styles and widths to openxml, one of:
    #       'dashDot'
    #       'dashDotDot'
    #       'dashed'
    #       'dotted'
    #       'double'
    #       'hair'
    #       'medium'
    #       'mediumDashDot'
    #       'mediumDashDotDot'
    #       'mediumDashed'
    #       'slantDashDot'
    #       'thick'
    #       'thin'
    if width is None and style is None:
        if color is None:
            # Return None will remove "border" from style dictionary
            return None
        else:
            # Return "none" will keep "border" in style dictionary
            return "none"

    if style in ("none", "hidden"):
        return "none"

    width_name = self._get_width_name(width)
    if width_name is None:
        return "none"

    if style in (None, "groove", "ridge", "inset", "outset", "solid"):
        # not handled
        return width_name

    if style == "double":
        return "double"
    if style == "dotted":
        if width_name in ("hair", "thin"):
            return "dotted"
        return "mediumDashDotDot"
    if style == "dashed":
        if width_name in ("hair", "thin"):
            return "dashed"
        return "mediumDashed"
    elif style in self.BORDER_STYLE_MAP:
        # Excel-specific styles
        return self.BORDER_STYLE_MAP[style]
    else:
        warnings.warn(
            f"Unhandled border style format: {style!r}",
            CSSWarning,
            stacklevel=find_stack_level(),
        )
        return "none"

def generate_filter_op(self, invert: bool = False):
    if (self.op == "!=" and not invert) or (self.op == "==" and invert):
        return lambda axis, vals: ~axis.isin(vals)
    else:
        return lambda axis, vals: axis.isin(vals)

def names(self):
    """
    Get the names in an expression.
    """
    if is_term(self.terms):
        return frozenset([self.terms.name])
    return frozenset(term.name for term in com.flatten(self.terms))

def __getstate__(self) -> dict[str, Any]:
    meta = {k: getattr(self, k, None) for k in self._metadata}
    return {
        "_mgr": self._mgr,
        "_typ": self._typ,
        "_metadata": self._metadata,
        "attrs": self.attrs,
        "_flags": {k: self.flags[k] for k in self.flags._keys},
        **meta,

def __from_arrow__(
    self, array: pyarrow.Array | pyarrow.ChunkedArray
) -> BaseStringArray:
    """
    Construct StringArray from pyarrow Array/ChunkedArray.
    """
    if self.storage == "pyarrow":
        from pandas.core.arrays.string_arrow import (
            ArrowStringArray,
            _check_pyarrow_available,
        )

        _check_pyarrow_available()

        if not pa.types.is_large_string(array.type):
            array = pc.cast(array, pa.large_string())

        return ArrowStringArray(array, dtype=self)

    else:
        import pyarrow

        if isinstance(array, pyarrow.Array):
            chunks = [array]
        else:
            # pyarrow.ChunkedArray
            chunks = array.chunks

        results = []
        for arr in chunks:
            # convert chunk by chunk to numpy and concatenate then, to avoid
            # overflow for large string data when concatenating the pyarrow arrays
            arr = arr.to_numpy(zero_copy_only=False)
            arr = ensure_string_array(arr, na_value=self.na_value)
            results.append(arr)

    if len(chunks) == 0:
        arr = np.array([], dtype=object)
    else:
        arr = np.concatenate(results)

    # Bypass validation inside StringArray constructor, see GH#47781
    new_string_array = StringArray.__new__(StringArray)
    NDArrayBacked.__init__(new_string_array, arr, self)
    return new_string_array

def value_counts(
    self,
    normalize: bool = False,
    sort: bool = True,
    ascending: bool = False,
    bins: int | None = None,
    dropna: bool = True,
) -> Series:
    from pandas import Series

    if bins is not None:
        return super().value_counts(
            normalize=normalize,
            sort=sort,
            ascending=ascending,
            bins=bins,
            dropna=dropna,
        )
    name = "proportion" if normalize else "count"
    data: npt.NDArray[np.floating] | npt.NDArray[np.signedinteger] = np.ones(
        len(self), dtype=np.int64
    )
    if normalize:
        data = data / len(self)
    return Series(data, index=self.copy(), name=name)

def pandasSQL_builder(
    con,
    schema: str | None = None,
    need_transaction: bool = False,
) -> PandasSQL:
    """
    Convenience function to return the correct PandasSQL subclass based on the
    provided parameters.  Also creates a sqlalchemy connection and transaction
    if necessary.
    """
    import sqlite3

    if isinstance(con, sqlite3.Connection) or con is None:
        return SQLiteDatabase(con)

    sqlalchemy = import_optional_dependency("sqlalchemy", errors="ignore")

    if isinstance(con, str) and sqlalchemy is None:
        raise ImportError(
            "Using a URI string requires 'sqlalchemy' version "
            f"'{VERSIONS['sqlalchemy']}' or newer."
        )

    if sqlalchemy is not None and isinstance(con, (str, sqlalchemy.engine.Connectable)):
        return SQLDatabase(con, schema, need_transaction)

    adbc = import_optional_dependency("adbc_driver_manager.dbapi", errors="ignore")
    if adbc and isinstance(con, adbc.Connection):
        return ADBCDatabase(con)

    warnings.warn(
        "pandas only supports SQLAlchemy connectable (engine/connection) or "
        "database string URI or sqlite3 DBAPI2 connection. Other DBAPI2 "
        "objects are not tested. Please consider using SQLAlchemy.",
        UserWarning,
        stacklevel=find_stack_level(),
    )
    return SQLiteDatabase(con)

def isin(self, values: ArrayLike) -> npt.NDArray[np.bool_]:
    if isinstance(values, BaseStringArray) or (
        isinstance(values, ExtensionArray) and is_string_dtype(values.dtype)
    ):
        values = values.astype(self.dtype, copy=False)
    else:
        if not lib.is_string_array(np.asarray(values), skipna=True):
            values = np.array(
                [val for val in values if isinstance(val, str) or isna(val)],
                dtype=object,
            )
            if not len(values):
                return np.zeros(self.shape, dtype=bool)

        values = self._from_sequence(values, dtype=self.dtype)

    return isin(np.asarray(self), np.asarray(values))

def _normalize_timezone_dtypes(df: pd.DataFrame) -> pd.DataFrame:
    """
    PyArrow below version 25 uses pytz by default for timezones, but pandas uses
    zoneinfo / datetime.timezone since pandas 3.0.

    Can be dropped once the minimum supported pyarrow is 25, which uses zoneinfo
    itself (https://github.com/apache/arrow/pull/49694).
    """
    if pytz is not None and pa_version_under25p0:
        # Convert any pytz timezones to zoneinfo / fixed offset timezones
        if any(
            isinstance(dtype, pd.DatetimeTZDtype)
            for dtype in df._mgr.get_unique_dtypes()
        ):
            col_indices = df._select_dtypes_indices(pd.DatetimeTZDtype)
            for i in col_indices:
                col = df.iloc[:, i]
                normalized_tz = _normalize_pytz_timezone(col.dtype.tz)
                if normalized_tz is not col.dtype.tz:
                    df.isetitem(i, col.dt.tz_convert(normalized_tz))

        df.index = _normalize_timezone_index(df.index)
        df.columns = _normalize_timezone_index(df.columns)

    return df

def _get_indexer_strict(
    self, key: Axes, axis_name: str_t
) -> tuple[Index, np.ndarray]:
    """
    Analogue to get_indexer that raises if any elements are missing.
    """
    keyarr = key
    if not isinstance(keyarr, Index):
        keyarr = com.asarray_tuplesafe(keyarr)

    if self._index_as_unique:
        indexer = self.get_indexer_for(keyarr)  # pyright: ignore[reportArgumentType]
        if not isinstance(keyarr, Index):
            keyarr = ensure_index(keyarr)
            keyarr.name = self.name
    else:
        keyarr, indexer, new_indexer = self._reindex_non_unique(keyarr)  # type: ignore[arg-type]  # pyright: ignore[reportArgumentType]

    self._raise_if_missing(keyarr, indexer, axis_name)

    keyarr = self.take(indexer)
    if lib.is_np_dtype(keyarr.dtype, "mM") or isinstance(
        keyarr.dtype, DatetimeTZDtype
    ):
        # DTI/TDI.take can infer a freq in some cases when we dont want one
        if isinstance(key, list) or (
            isinstance(key, type(self))
            # "Index" has no attribute "freq"
            and key.freq is None  # type: ignore[attr-defined]
        ):
            # error: "Index" has no attribute "_with_freq"; maybe "_with_infer"?
            keyarr = keyarr._with_freq(None)  # type: ignore[attr-defined]

    return keyarr, indexer

def _str_map(
    self,
    f,
    na_value=lib.no_default,
    dtype: NpDtype | None = None,
    convert: bool = True,
):
    """
    Map a callable over valid elements of the array.

    Parameters
    ----------
    f : Callable
        A function to call on each non-NA element.
    na_value : Scalar, optional
        The value to set for NA values. Might also be used for the
        fill value if the callable `f` raises an exception.
        This defaults to ``self.dtype.na_value`` which is ``np.nan``
        for object-dtype and Categorical and ``pd.NA`` for StringArray.
    dtype : Dtype, optional
        The dtype of the result array.
    convert : bool, default True
        Whether to call `maybe_convert_objects` on the resulting ndarray
    """
    if dtype is None:
        dtype = np.dtype("object")
    if na_value is lib.no_default:
        na_value = self.dtype.na_value  # type: ignore[attr-defined]

    if not len(self):
        return np.array([], dtype=dtype)

    arr = np.asarray(self, dtype=object)
    mask = isna(arr)
    map_convert = convert and not np.all(mask)
    try:
        result = lib.map_infer_mask(
            arr, f, mask.view(np.uint8), convert=map_convert
        )
    except (TypeError, AttributeError) as err:
        # Reraise the exception if callable `f` got wrong number of args.
        # The user may want to be warned by this, instead of getting NaN
        p_err = (
            r"((takes)|(missing)) (?(2)from \d+ to )?\d+ "
            r"(?(3)required )positional arguments?"
        )

        if len(err.args) >= 1 and re.search(p_err, err.args[0]):
            # NOTE: matches CPython's TypeError when a user-supplied
            # callable (e.g. `repl` in str.replace) is called with the
            # wrong number of positional arguments.
            raise err

        def g(x):
            # This type of fallback behavior can be removed once
            # we remove object-dtype .str accessor.
            try:
                return f(x)
            except (TypeError, AttributeError):
                return na_value

        return self._str_map(g, na_value=na_value, dtype=dtype)
    if not isinstance(result, np.ndarray):
        return result
    if na_value is not np.nan:
        np.putmask(result, mask, na_value)
        if convert and result.dtype == object:
            result = lib.maybe_convert_objects(result)
    return result

def prune(self, klass):
    if self.op != "~":
        raise NotImplementedError("UnaryOp only support invert type ops")

    operand = self.operand
    operand = operand.prune(klass)

    if operand is not None and (
        (issubclass(klass, ConditionBinOp) and operand.condition is not None)
        or (
            not issubclass(klass, ConditionBinOp)
            and issubclass(klass, FilterBinOp)
            and operand.filter is not None
        )
    ):
        return operand.invert()
    return None

def _select_data(self) -> DataFrame:
    """Select columns to be described."""
    if (self.include is None) and (self.exclude is None):
        # when some numerics are found, keep only numerics
        default_include: list[npt.DTypeLike] = [np.number, "datetime"]
        data = self.obj.select_dtypes(include=default_include)
        if len(data.columns) == 0:
            data = self.obj
    elif isinstance(self.include, str) and self.include == "all":
        # isinstance guard so an array-like spec is not compared elementwise
        if self.exclude is not None:
            msg = "exclude must be None when include is 'all'"
            raise ValueError(msg)
        data = self.obj
    else:
        data = self.obj.select_dtypes(
            include=self.include,
            exclude=self.exclude,
        )
        if len(data.columns) == 0:
            msg = "No columns match the specified include or exclude data types"
            raise ValueError(msg)
    return data

def _is_monotonic_decreasing(self) -> bool:
    pa_array = self._pa_array
    if pa_array.null_count > 0:
        return False
    if len(pa_array) <= 1:
        return True
    try:
        return pc.all(pc.less_equal(pa_array[1:], pa_array[:-1])).as_py()
    except pa.ArrowNotImplementedError:
        # If the type doesn't support comparison, e.g. list types
        return False

def __init__(
    self,
    storage: str | None = None,
    na_value: libmissing.NAType | float = libmissing.NA,
) -> None:
    # infer defaults
    if storage is None:
        storage = config["mode"]["string_storage"]
        if storage == "auto":
            if HAS_PYARROW:
                storage = "pyarrow"
            else:
                storage = "python"

    # validate options
    if storage not in {"python", "pyarrow"}:
        raise ValueError(
            f"Storage must be 'python' or 'pyarrow'. Got {storage} instead."
        )
    if storage == "pyarrow" and not HAS_PYARROW:
        raise ImportError(
            f"pyarrow>={PYARROW_MIN_VERSION} is required for PyArrow "
            "backed StringArray."
        )

    if isinstance(na_value, float) and np.isnan(na_value):
        # when passed a NaN value, always set to np.nan to ensure we use
        # a consistent NaN value (and we can use `dtype.na_value is np.nan`)
        na_value = np.nan
    elif na_value is not libmissing.NA:
        raise ValueError(f"'na_value' must be np.nan or pd.NA, got {na_value}")

    self._storage = cast("str", storage)
    self._na_value = na_value

def _get_layout(
    nplots: int,
    layout: tuple[int, int] | None = None,
    layout_type: str = "box",
) -> tuple[int, int]:
    if layout is not None:
        if not isinstance(layout, (tuple, list)) or len(layout) != 2:
            raise ValueError("Layout must be a tuple of (rows, columns)")

        nrows, ncols = layout

        if nrows == -1 and ncols > 0:
            layout = (ceil(nplots / ncols), ncols)
        elif ncols == -1 and nrows > 0:
            layout = (nrows, ceil(nplots / nrows))
        elif ncols <= 0 and nrows <= 0:
            msg = "At least one dimension of layout must be positive"
            raise ValueError(msg)

        nrows, ncols = layout
        if nrows * ncols < nplots:
            raise ValueError(
                f"Layout of {nrows}x{ncols} must be larger than required size {nplots}"
            )

        return layout

    if layout_type == "single":
        return (1, 1)
    elif layout_type == "horizontal":
        return (1, nplots)
    elif layout_type == "vertical":
        return (nplots, 1)

    layouts = {1: (1, 1), 2: (1, 2), 3: (2, 2), 4: (2, 2)}
    try:
        return layouts[nplots]
    except KeyError:
        k = 1
        while k**2 < nplots:
            k += 1

        if (k - 1) * k >= nplots:
            return k, (k - 1)
        else:
            return k, k

def __getattr__(self, attr: str):
    if attr in self._internal_names_set:
        return object.__getattribute__(self, attr)
    if attr in self._attributes:
        return getattr(self._timegrouper, attr)
    if attr in self.obj:
        return self[attr]

    return object.__getattribute__(self, attr)

def _get_prev_label(label):
    # see test_slice_locs_with_ints_and_floats_succeeds
    dtype = getattr(label, "dtype", type(label))
    if isinstance(label, (Timestamp, Timedelta)):
        dtype = "datetime64[ns]"
    dtype = pandas_dtype(dtype)

    if lib.is_np_dtype(dtype, "mM") or isinstance(dtype, DatetimeTZDtype):
        return label - np.timedelta64(1, "ns")
    elif is_integer_dtype(dtype):
        return label - 1
    elif is_float_dtype(dtype):
        return np.nextafter(label, -np.inf)
    else:
        raise TypeError(f"cannot determine next label for type {type(label)!r}")

def __rtruediv__(self, other):
    # X / timedelta is defined only for timedelta-like X
    op = roperator.rtruediv
    if is_scalar(other):
        return self._scalar_divlike_op(other, op)

    other = self._cast_divlike_op(other)
    if lib.is_np_dtype(other.dtype, "m"):
        return self._vector_divlike_op(other, op)

    elif is_object_dtype(other.dtype):
        # Note: unlike in __truediv__, we do not _need_ to do type
        #  inference on the result.  It does not raise, a numeric array
        #  is returned.  GH#23829
        result_list = [other[n] / self[n] for n in range(len(self))]
        return np.array(result_list)

    else:
        return NotImplemented

def astype(self, dtype, copy: bool = True):
    dtype = pandas_dtype(dtype)

    if dtype == self.dtype:
        if copy:
            return self.copy()
        return self

    elif isinstance(dtype, IntegerDtype):
        arr = self._ndarray.copy()
        mask = self.isna()
        arr[mask] = 0
        values = arr.astype(dtype.numpy_dtype)
        return IntegerArray(values, mask, copy=False)
    elif isinstance(dtype, FloatingDtype):
        arr_ea = self.copy()
        mask = self.isna()
        arr_ea[mask] = "0"
        values = arr_ea.astype(dtype.numpy_dtype)
        return FloatingArray(values, mask, copy=False)
    elif isinstance(dtype, ExtensionDtype):
        # Skip the NumpyExtensionArray.astype method
        return ExtensionArray.astype(self, dtype, copy)
    elif np.issubdtype(dtype, np.floating):
        arr = self._ndarray.copy()
        mask = self.isna()
        arr[mask] = 0
        values = arr.astype(dtype)
        values[mask] = np.nan
        return values

    return super().astype(dtype, copy)

def __getattr__(key: str) -> object:
    # These imports need to be lazy to avoid circular import errors
    if key == "hash_array":
        from pandas.core.util.hashing import hash_array

        return hash_array
    if key == "hash_pandas_object":
        from pandas.core.util.hashing import hash_pandas_object

        return hash_pandas_object
    if key == "Appender":
        from pandas.util._decorators import Appender

        return Appender
    if key == "Substitution":
        from pandas.util._decorators import Substitution

        return Substitution

    if key == "cache_readonly":
        from pandas.util._decorators import cache_readonly

        return cache_readonly

    raise AttributeError(f"module 'pandas.util' has no attribute '{key}'")

def _filter_usecols(usecols, names: SequenceT) -> SequenceT | list[Hashable]:
    # hackish
    usecols = evaluate_callable_usecols(usecols, names)
    if usecols is not None and len(names) != len(usecols):
        return [name for i, name in enumerate(names) if i in usecols or name in usecols]
    return names

def _get_next_label(label):
    # see test_slice_locs_with_ints_and_floats_succeeds
    dtype = getattr(label, "dtype", type(label))
    if isinstance(label, (Timestamp, Timedelta)):
        dtype = "datetime64[ns]"
    dtype = pandas_dtype(dtype)

    if lib.is_np_dtype(dtype, "mM") or isinstance(dtype, DatetimeTZDtype):
        return label + np.timedelta64(1, "ns")
    elif is_integer_dtype(dtype):
        return label + 1
    elif is_float_dtype(dtype):
        return np.nextafter(label, np.inf)
    else:
        raise TypeError(f"cannot determine next label for type {type(label)!r}")

def _internal_get_values(self) -> ArrayLike:
    """
    Return the values.

    For internal compatibility with pandas formatting.

    Returns
    -------
    np.ndarray or ExtensionArray
        A numpy array or ExtensionArray of the same dtype as
        categorical.categories.dtype.
    """
    # if we are a datetime and period index, return Index to keep metadata
    if needs_i8_conversion(self.categories.dtype):
        return self.categories.take(
            self._codes, allow_fill=True, fill_value=NaT
        )._values
    elif is_integer_dtype(self.categories.dtype) and -1 in self._codes:
        return (
            self.categories.astype("object")
            .take(self._codes, allow_fill=True, fill_value=np.nan)
            ._values
        )
    return np.array(self)

def _str_fullmatch(
    self,
    pat: str | re.Pattern,
    case: bool = True,
    flags: int = 0,
    na: Scalar | lib.NoDefault = lib.no_default,
):
    pat, case, flags = self._unwrap_re_pattern(pat, case, flags)

    if (not pat.endswith("$") or pat.endswith("\\$")) and not pat.startswith("^"):
        pat = f"^({pat})$"
    elif not pat.endswith("$") or pat.endswith("\\$"):
        pat = f"^({pat[1:]})$"
    elif not pat.startswith("^"):
        pat = f"^({pat[0:-1]})$"
    return ArrowStringArrayMixin._str_match(self, pat, case, flags, na)

def add_body_lines(self) -> None:
    for row in self.strrows:
        body_line = self.SPACING.join(
            [
                self._ljust(col, gross_colwidth)
                for col, gross_colwidth in zip(
                    row, self.gross_column_widths, strict=True
                )
            ]
        )
        self._lines.append(body_line)

def _convert_grouper(axis: Index, grouper):
    if isinstance(grouper, dict):
        return grouper.get
    elif isinstance(grouper, Series):
        if grouper.index.equals(axis):
            return grouper._values
        else:
            return grouper.reindex(axis)._values
    elif isinstance(grouper, MultiIndex):
        return grouper._values
    elif isinstance(grouper, (list, tuple, Index, Categorical, np.ndarray)):
        if len(grouper) != len(axis):
            raise ValueError("Grouper and axis must be same length")

        if isinstance(grouper, (list, tuple)):
            grouper = com.asarray_tuplesafe(grouper)
        return grouper
    else:
        return grouper

def __eq__(self, other):
    if isinstance(other, pyarrow.BaseExtensionType):
        return (
            type(self) == type(other)
            and self.subtype == other.subtype
            and self.closed == other.closed
        )
    else:
        return NotImplemented

def _engine(
    self,
) -> libindex.IndexEngine | libindex.ExtensionEngine | libindex.MaskedIndexEngine:
    # For base class (object dtype) we get ObjectEngine
    dtype = self.dtype
    target_values = self._get_engine_target()

    if isinstance(dtype, ArrowDtype) and dtype.kind in "Mm":
        import pyarrow as pa

        values = self._values
        pa_type = values._pa_array.type  # type: ignore[union-attr]
        if pa.types.is_timestamp(pa_type):
            target_values = values._to_datetimearray()  # type: ignore[union-attr]
            return libindex.DatetimeEngine(target_values._ndarray)
        elif pa.types.is_duration(pa_type):
            target_values = values._to_timedeltaarray()  # type: ignore[union-attr]
            return libindex.TimedeltaEngine(target_values._ndarray)

    if isinstance(target_values, ExtensionArray):
        if isinstance(target_values, (BaseMaskedArray, ArrowExtensionArray)):
            try:
                return _masked_engines[target_values.dtype.name](target_values)
            except KeyError:
                # Not supported yet e.g. decimal
                pass
        elif self._engine_type is libindex.ObjectEngine:
            return libindex.ExtensionEngine(target_values)

    # to avoid a reference cycle, bind `target_values` to a local variable, so
    # `self` is not passed into the lambda.
    if target_values.dtype == bool:
        return libindex.BoolEngine(target_values)  # type: ignore[arg-type]
    elif target_values.dtype == np.complex64:
        return libindex.Complex64Engine(target_values)  # type: ignore[arg-type]
    elif target_values.dtype == np.complex128:
        return libindex.Complex128Engine(target_values)  # type: ignore[arg-type]
    elif needs_i8_conversion(dtype):
        # We need to keep M8/m8 dtype when initializing the Engine,
        #  but don't want to change _get_engine_target bc it is used
        #  elsewhere
        # error: Item "ExtensionArray" of "Union[ExtensionArray,
        # ndarray[Any, Any]]" has no attribute "_ndarray"  [union-attr]
        target_values = self._data._ndarray  # type: ignore[union-attr]
    elif isinstance(dtype, StringDtype):
        return libindex.StringObjectEngine(target_values, dtype.na_value)

    # error: Argument 1 to "ExtensionEngine" has incompatible type
    # "ndarray[Any, Any]"; expected "ExtensionArray"
    return self._engine_type(target_values)  # type: ignore[arg-type]

def _truthy_value(self):
    # Fill values used for 'any'
    if self.kind == "f":
        return 1.0
    if self.kind in "iu":
        return 1
    return True

def __repr__(self) -> str:
    info = ""
    if self.year is not None:
        info += f"year={self.year}, "
    info += f"month={self.month}, day={self.day}, "

    if self.offset is not None:
        info += f"offset={self.offset}"

    if self.observance is not None:
        info += f"observance={self.observance}"

    repr = f"Holiday: {self.name} ({info})"
    return repr

def _reduce_calc(
    self, name: str, *, skipna: bool = True, keepdims: bool = False, **kwargs
):
    pa_result = self._reduce_pyarrow(name, skipna=skipna, **kwargs)

    if keepdims:
        if isinstance(pa_result, pa.Scalar):
            result = pa.array([pa_result.as_py()], type=pa_result.type)
        else:
            result = pa.array(
                [pa_result],
                type=to_pyarrow_type(infer_dtype_from_scalar(pa_result)[0]),
            )
        return result

    if pc.is_null(pa_result).as_py():
        return self.dtype.na_value
    elif isinstance(pa_result, pa.Scalar):
        result = pa_result.as_py()
        pa_type = pa_result.type
        if pa.types.is_duration(pa_type) and pa_type.unit != "ns":
            return Timedelta(result).as_unit(pa_type.unit)
        elif pa.types.is_timestamp(pa_type) and pa_type.unit != "ns":
            return Timestamp(result).as_unit(pa_type.unit)
        return result
    else:
        return pa_result

def _get_cython_function(
    cls, kind: str, how: str, dtype: np.dtype, is_numeric: bool
):
    dtype_str = dtype.name
    ftype = cls._CYTHON_FUNCTIONS[kind][how]

    # see if there is a fused-type version of function
    # only valid for numeric
    if callable(ftype):
        f = ftype
    else:
        f = getattr(libgroupby, ftype)
    if is_numeric:
        return f
    elif dtype == np.dtype(object):
        if how in ["median", "cumprod"]:
            # no fused types -> no __signatures__
            raise NotImplementedError(
                f"function is not implemented for this dtype: "
                f"[how->{how},dtype->{dtype_str}]"
            )
        elif how in ["std", "sem", "idxmin", "idxmax"]:
            # We have a partial object that does not have __signatures__
            return f
        elif how in ["skew", "kurt"]:
            # _get_cython_vals will convert to float64
            pass
        elif "object" not in f.__signatures__:
            # raise NotImplementedError here rather than TypeError later
            raise NotImplementedError(
                f"function is not implemented for this dtype: "
                f"[how->{how},dtype->{dtype_str}]"
            )
        return f
    else:
        raise NotImplementedError(
            "This should not be reached. Please report a bug at "
            "github.com/pandas-dev/pandas/",
            dtype,

def _mask_datetimelike_result(
    result: np.ndarray | np.datetime64 | np.timedelta64,
    axis: AxisInt | None,
    mask: npt.NDArray[np.bool_],
    orig_values: np.ndarray,
) -> np.ndarray | np.datetime64 | np.timedelta64 | NaTType:
    if isinstance(result, np.ndarray):
        # we need to apply the mask
        result = result.astype("i8").view(orig_values.dtype)
        axis_mask = mask.any(axis=axis)
        result[axis_mask] = iNaT
    elif mask.any():
        return np.int64(iNaT).view(orig_values.dtype)
    return result

def _str_split(
    self,
    pat: str | re.Pattern | None = None,
    n=-1,
    expand: bool = False,
    regex: bool | None = None,
):
    if pat is None:
        if n is None or n == 0:
            n = -1
        f = lambda x: x.split(pat, n)
    else:
        new_pat: str | re.Pattern
        if regex is True or isinstance(pat, re.Pattern):
            new_pat = re.compile(pat)
        elif regex is False:
            new_pat = pat
        # regex is None so link to old behavior #43563
        elif len(pat) == 1:
            new_pat = pat
        else:
            new_pat = re.compile(pat)

        if isinstance(new_pat, re.Pattern):
            if n is None or n == -1:
                n = 0
            f = lambda x: new_pat.split(x, maxsplit=n)
        else:
            if n is None or n == 0:
                n = -1
            f = lambda x: x.split(pat, n)
    return self._str_map(f, dtype=object)

def get_numeric_data(self) -> Self:
    numeric_blocks = [blk for blk in self.blocks if blk.is_numeric]
    if len(numeric_blocks) == len(self.blocks):
        # Avoid somewhat expensive _combine
        # TODO(CoW) need to return a shallow copy here?
        return self
    return self._combine(numeric_blocks)

def apply_series_numba(self):
    if self.engine_kwargs.get("parallel", False):
        raise NotImplementedError(
            "Parallel apply is not supported when raw=False and engine='numba'"
        )
    if not self.obj.index.is_unique or not self.columns.is_unique:
        raise NotImplementedError(
            "The index/columns must be unique when raw=False and engine='numba'"
        )
    self.validate_values_for_numba()
    results = self.apply_with_numba()
    return results, self.result_index

def astype(self, dtype, copy: bool = True):
    """
    Cast to an ExtensionArray or NumPy array with dtype 'dtype'.

    Parameters
    ----------
    dtype : str or dtype
        Typecode or data-type to which the array is cast.

    copy : bool, default True
        Whether to copy the data, even if not necessary. If False,
        a copy is made only if the old dtype does not match the
        new dtype.

    Returns
    -------
    array : ExtensionArray or ndarray
        ExtensionArray or NumPy ndarray with 'dtype' for its dtype.
    """
    from pandas import Index

    if dtype is not None:
        dtype = pandas_dtype(dtype)

    if isinstance(dtype, IntervalDtype):
        if dtype == self.dtype:
            return self.copy() if copy else self

        if is_float_dtype(self.dtype.subtype) and needs_i8_conversion(
            dtype.subtype
        ):
            # This is allowed on the Index.astype but we disallow it here
            msg = (
                f"Cannot convert {self.dtype} to {dtype}; subtypes are incompatible"
            )
            raise TypeError(msg)

        # need to cast to different subtype
        try:
            # We need to use Index rules for astype to prevent casting
            #  np.nan entries to int subtypes
            new_left = Index(self._left, copy=False).astype(dtype.subtype)
            new_right = Index(self._right, copy=False).astype(dtype.subtype)
        except IntCastingNaNError:
            # e.g test_subtype_integer
            raise
        except (TypeError, ValueError) as err:
            # e.g. test_subtype_integer_errors f8->u8 can be lossy
            #  and raises ValueError
            msg = (
                f"Cannot convert {self.dtype} to {dtype}; subtypes are incompatible"
            )
            raise TypeError(msg) from err
        return self._shallow_copy(new_left, new_right)
    else:
        try:
            return super().astype(dtype, copy=copy)
        except (TypeError, ValueError) as err:
            msg = f"Cannot cast {type(self).__name__} to dtype {dtype}"
            raise TypeError(msg) from err

def __rmatmul__(self, other) -> DataFrame:
    """
    Matrix multiplication using binary `@` operator.
    """
    try:
        return self.T.dot(np.transpose(other)).T
    except ValueError as err:
        if "shape mismatch" not in str(err):
            raise
        # GH#21581 give exception message for original shapes
        msg = f"shapes {np.shape(other)} and {self.shape} not aligned"
        raise ValueError(msg) from err

def validate_attr(self, append) -> None:
    """validate that we have the same order as the existing & same dtype"""
    if append:
        existing_fields = getattr(self.attrs, self.kind_attr, None)
        if existing_fields is not None and existing_fields != list(self.values):
            raise ValueError("appended items do not match existing items in table!")

        existing_dtype = getattr(self.attrs, self.dtype_attr, None)
        if existing_dtype is not None and existing_dtype != self.dtype:
            raise ValueError(
                "appended items dtype do not match existing items dtype in table!"

def _header_line(self):
    # Store line for reuse in _get_index_name
    if self.header is not None:
        return None

    try:
        line = self._buffered_line()
    except StopIteration as err:
        if not self.names:
            raise EmptyDataError("No columns to parse from file") from err

        line = self.names[:]
    return line

def _falsey_value(self):
    # Fill values used for 'all'
    if self.kind == "f":
        return 0.0
    if self.kind in "iu":
        return 0
    return False

def _join_empty(
    self, other: Index, how: JoinHow, sort: bool
) -> tuple[Index, npt.NDArray[np.intp] | None, npt.NDArray[np.intp] | None]:
    assert len(self) == 0 or len(other) == 0
    _validate_join_method(how)

    lidx: np.ndarray | None
    ridx: np.ndarray | None

    if len(other):
        how = cast("JoinHow", {"left": "right", "right": "left"}.get(how, how))
        join_index, ridx, lidx = other._join_empty(self, how, sort)
    elif how in ["left", "outer"]:
        if sort and not self.is_monotonic_increasing:
            lidx = self.argsort()
            join_index = self.take(lidx)
        else:
            lidx = None
            join_index = self._view()
        ridx = np.broadcast_to(np.intp(-1), len(join_index))
    else:
        join_index = other._view()
        lidx = np.array([], dtype=np.intp)
        ridx = None
    return join_index, lidx, ridx

def agg_or_apply_dict_like(
    self, op_name: Literal["agg", "apply"]
) -> DataFrame | Series:
    from pandas.core.groupby.generic import (
        DataFrameGroupBy,
        SeriesGroupBy,
    )

    assert op_name in ["agg", "apply"]

    obj = self.obj
    kwargs: dict[str, Any] = {}
    if op_name == "apply":
        by_row = "_compat" if self.by_row else False
        kwargs.update({"by_row": by_row})

    if getattr(obj, "axis", 0) == 1:
        raise NotImplementedError("axis other than 0 is not supported")

    selected_obj = obj._selected_obj
    selection = obj._selection

    is_groupby = isinstance(obj, (DataFrameGroupBy, SeriesGroupBy))

    # Numba Groupby engine/engine-kwargs passthrough
    if is_groupby:
        engine = self.kwargs.get("engine", None)
        engine_kwargs = self.kwargs.get("engine_kwargs", None)
        kwargs.update({"engine": engine, "engine_kwargs": engine_kwargs})

    with com.temp_setattr(
        obj, "as_index", True, condition=hasattr(obj, "as_index")
    ):
        result_index, result_data = self.compute_dict_like(
            op_name, selected_obj, selection, kwargs
        )
    result = self.wrap_results_dict_like(selected_obj, result_index, result_data)
    return result

def _get_required_dependencies_from_pixi_content(
    content: list[str], pixi_toml: dict[str, Any]
) -> dict[str, str]:
    # pixi.toml keeps build and required deps in the same TOML table.
    required_deps = {}
    in_dependencies = False
    in_required_dependencies = False
    for line in content:
        line = line.strip()
        if not line:
            continue
        if line.startswith("["):
            in_dependencies = line == "[dependencies]"
            in_required_dependencies = False
            continue
        if not in_dependencies:
            continue
        if line.casefold() == "# required dependencies":
            in_required_dependencies = True
            continue
        if line.startswith("#"):
            in_required_dependencies = False
            continue
        if not in_required_dependencies:
            continue
        package = line.split("=", maxsplit=1)[0].strip()
        version = _get_version_from_pixi_spec(pixi_toml["dependencies"][package])
        if version is not None and package not in EXCLUDE_DEPS:
            required_deps[package.casefold()] = version
    return required_deps

def __init__(
    self,
    path: FilePath | WriteExcelBuffer | ExcelWriter,
    engine: str | None = None,
    date_format: str | None = None,
    datetime_format: str | None = None,
    mode: str = "w",
    storage_options: StorageOptions | None = None,
    if_sheet_exists: ExcelWriterIfSheetExists | None = None,
    engine_kwargs: dict[str, Any] | None = None,
) -> None:
    # validate that this engine can handle the extension
    if isinstance(path, str):
        ext = os.path.splitext(path)[-1]
        self.check_extension(ext)

    # use mode to open the file
    if "b" not in mode:
        mode += "b"
    # use "a" for the user to append data to excel but internally use "r+" to let
    # the excel backend first read the existing file and then write any data to it
    mode = mode.replace("a", "r+")

    if if_sheet_exists not in (None, "error", "new", "replace", "overlay"):
        raise ValueError(
            f"'{if_sheet_exists}' is not valid for if_sheet_exists. "
            "Valid options are 'error', 'new', 'replace' and 'overlay'."
        )
    if if_sheet_exists and "r+" not in mode:
        raise ValueError("if_sheet_exists is only valid in append mode (mode='a')")
    if if_sheet_exists is None:
        if_sheet_exists = "error"
    self._if_sheet_exists = if_sheet_exists

    # cast ExcelWriter to avoid adding 'if self._handles is not None'
    self._handles = IOHandles(
        cast("IO[bytes]", path), compression={"compression": None}
    )
    if not isinstance(path, ExcelWriter):
        self._handles = get_handle(
            path, mode, storage_options=storage_options, is_text=False
        )
    self._cur_sheet = None

    if date_format is None:
        self._date_format = "YYYY-MM-DD"
    else:
        self._date_format = date_format
    if datetime_format is None:
        self._datetime_format = "YYYY-MM-DD HH:MM:SS"
    else:
        self._datetime_format = datetime_format

    self._mode = mode

def __init__(
    self, values, *, dtype: StringDtype | None = None, copy: bool = False
) -> None:
    if dtype is None:
        dtype = StringDtype()
    values = extract_array(values)

    super().__init__(values, copy=copy)
    if not isinstance(values, type(self)):
        self._validate(dtype)
    NDArrayBacked.__init__(
        self,
        self._ndarray,
        dtype,

def _public_names() -> frozenset[str]:
    """Return ``pandas.__all__``, read without importing pandas."""
    path = Path(__file__).parent.parent / "pandas" / "__init__.py"
    tree = ast.parse(path.read_text(encoding="utf-8"))
    for node in tree.body:
        if (
            isinstance(node, ast.Assign)
            and any(
                isinstance(target, ast.Name) and target.id == "__all__"
                for target in node.targets
            )
            and isinstance(node.value, ast.List)
        ):
            return frozenset(
                element.value
                for element in node.value.elts
                if isinstance(element, ast.Constant)
            )
    raise AssertionError(f"could not find __all__ in {path}")

def set_ticks_props(
    axes: Axes | Iterable[Axes],
    xlabelsize: int | None = None,
    xrot=None,
    ylabelsize: int | None = None,
    yrot=None,
):
    for ax in flatten_axes(axes):
        if xlabelsize is not None:
            mpl.artist.setp(ax.get_xticklabels(), fontsize=xlabelsize)  # type: ignore[arg-type]
        if xrot is not None:
            mpl.artist.setp(ax.get_xticklabels(), rotation=xrot)  # type: ignore[arg-type]
        if ylabelsize is not None:
            mpl.artist.setp(ax.get_yticklabels(), fontsize=ylabelsize)  # type: ignore[arg-type]
        if yrot is not None:
            mpl.artist.setp(ax.get_yticklabels(), rotation=yrot)  # type: ignore[arg-type]
    return axes

def _read_strls(self) -> None:
    self._path_or_buf.seek(self._seek_strls)
    # Wrap v_o in a string to allow uint64 values as keys on 32bit OS
    self.GSO = {"0": ""}
    while True:
        if self._path_or_buf.read(3) != b"GSO":
            break

        if self._format_version == 117:
            v_o = self._read_uint64()
        else:
            buf = self._path_or_buf.read(12)
            # Only tested on little endian machine.
            v_size = 2 if self._format_version == 118 else 3
            if self._byteorder == "<":
                buf = buf[0:v_size] + buf[4 : (12 - v_size)]
            else:
                buf = buf[4 - v_size : 4] + buf[(4 + v_size) :]
            v_o = struct.unpack(f"{self._byteorder}Q", buf)[0]
        typ = self._read_uint8()
        length = self._read_uint32()
        va = self._path_or_buf.read(length)
        if typ == 130:
            decoded_va = va[0:-1].decode(self._encoding)
        else:
            # Stata says typ 129 can be binary, so use str
            decoded_va = str(va)
            # Wrap v_o in a string to allow uint64 values as keys on 32bit OS
        self.GSO[str(v_o)] = decoded_va

def _col_idx_to_axis_idx(self, col_idx: int) -> int:
    """Return the index of the axis where the column at col_idx should be plotted"""
    if isinstance(self.subplots, list):
        # Subplots is a list: some columns will be grouped together in the same ax
        return next(
            group_idx
            for (group_idx, group) in enumerate(self.subplots)
            if col_idx in group
        )
    else:
        # subplots is True: one ax per column
        return col_idx

def _get_common_dtype(self, dtypes: list[DtypeObj]) -> DtypeObj | None:
    # We unwrap any masked dtypes, find the common dtype we would use
    #  for that, then re-mask the result.
    from pandas.core.dtypes.cast import find_common_type

    new_dtype = find_common_type(
        [
            dtype.numpy_dtype if isinstance(dtype, BaseMaskedDtype) else dtype
            for dtype in dtypes
        ]
    )
    if not isinstance(new_dtype, np.dtype):
        # If we ever support e.g. Masked[DatetimeArray] then this will change
        return None
    try:
        return type(self).from_numpy_dtype(new_dtype)
    except (KeyError, NotImplementedError):
        return None

def _set_endianness(endianness: str) -> str:
    if endianness.lower() in ["<", "little"]:
        return "<"
    elif endianness.lower() in [">", "big"]:
        return ">"
    else:  # pragma : no cover
        raise ValueError(f"Endianness {endianness} not understood")

def is_nested_tuple(tup, labels) -> bool:
    """
    Returns
    -------
    bool
    """
    # check for a compatible nested tuple and multiindexes among the axes
    if not isinstance(tup, tuple):
        return False

    for k in tup:
        if is_list_like(k) or isinstance(k, slice):
            return isinstance(labels, MultiIndex)

    return False

def _post_plot_logic(self, ax: Axes, data) -> None:
    # GH 45465: make sure that the boxplot doesn't ignore xlabel/ylabel
    if self.xlabel:
        ax.set_xlabel(pprint_thing(self.xlabel))
    if self.ylabel:
        ax.set_ylabel(pprint_thing(self.ylabel))

def _validate_dtype(cls, dtype) -> DtypeObj | None:
    """validate the passed dtype"""
    if dtype is not None:
        dtype = pandas_dtype(dtype)

        # a compound dtype
        if dtype.kind == "V" and not isinstance(dtype, ExtensionDtype):
            raise NotImplementedError(
                "compound dtypes are not implemented "
                f"in the {cls.__name__} constructor"
            )

    return dtype

def _get_column_weights(weights, i: int, y):
    # We allow weights to be a multi-dimensional array, e.g. a (10, 2) array,
    # and each sub-array (10,) will be called in each iteration. If users only
    # provide 1D array, we assume the same weights is used for all iterations
    if weights is not None:
        if np.ndim(weights) != 1 and np.shape(weights)[-1] != 1:
            try:
                weights = weights[:, i]
            except IndexError as err:
                raise ValueError(
                    "weights must have the same shape as data, "
                    "or be a single column"
                ) from err
        weights = weights[~isna(y)]
    return weights

def _adjust_bins(self, bins: int | np.ndarray | list[np.ndarray]):
    if is_integer(bins):
        if self.by is not None:
            by_modified = unpack_single_str_list(self.by)
            grouped = self.data.groupby(by_modified)[self.columns]
            bins = [self._calculate_bins(group, bins) for key, group in grouped]
        else:
            bins = self._calculate_bins(self.data, bins)
    return bins

def argmax(self, axis: AxisInt = 0, skipna: bool = True):  # type: ignore[override]
    # override base class by adding axis keyword
    validate_bool_kwarg(skipna, "skipna")
    if not skipna and self._hasna:
        raise ValueError("Encountered an NA value with skipna=False")
    return nargminmax(self, "argmax", axis=axis)

def _get_out_dtype(self, dtype: np.dtype) -> np.dtype:
    how = self.how

    if how == "rank":
        out_dtype = "float64"
    elif how in ["idxmin", "idxmax"]:
        # The Cython implementation only produces the row number; we'll take
        # from the index using this in post processing
        out_dtype = "intp"
    elif dtype.kind in "iufcb":
        out_dtype = f"{dtype.kind}{dtype.itemsize}"
    else:
        out_dtype = "object"
    return np.dtype(out_dtype)

def __arrow_array__(self, type=None):
    """
    Convert myself into a pyarrow Array.
    """
    import pyarrow

    from pandas.core.arrays.arrow.array import to_pyarrow_type
    from pandas.core.arrays.arrow.extension_types import ArrowIntervalType

    try:
        subtype = to_pyarrow_type(self.dtype.subtype)
    except (TypeError, pyarrow.ArrowNotImplementedError) as err:
        raise TypeError(
            f"Conversion to arrow with subtype '{self.dtype.subtype}' "
            "is not supported"
        ) from err
    if subtype is None:
        raise TypeError(
            f"Conversion to arrow with subtype '{self.dtype.subtype}' "
            "is not supported"
        )
    interval_type = ArrowIntervalType(subtype, self.closed)

    def _to_arrow(values) -> pyarrow.Array:
        if isinstance(self.dtype.subtype, np.dtype):
            return pyarrow.array(values, type=subtype, from_pandas=True)
        # pyarrow would fall back on `.values`, dropping the tz; _ndarray is UTC
        return pyarrow.array(values._ndarray, from_pandas=True).cast(subtype)

    storage_array = pyarrow.StructArray.from_arrays(
        [_to_arrow(self._left), _to_arrow(self._right)],
        names=["left", "right"],
    )
    mask = self.isna()
    if mask.any():
        # if there are missing values, set validity bitmap also on the array level
        null_bitmap = pyarrow.array(~mask).buffers()[1]
        storage_array = pyarrow.StructArray.from_buffers(
            storage_array.type,
            len(storage_array),
            [null_bitmap],
            children=[storage_array.field(0), storage_array.field(1)],
        )

    if type is not None:
        if type.equals(interval_type.storage_type):
            return storage_array
        elif isinstance(type, ArrowIntervalType):
            # ensure we have the same subtype and closed attributes
            if not type.equals(interval_type):
                raise TypeError(
                    "Not supported to convert IntervalArray to type with "
                    f"different 'subtype' ({self.dtype.subtype} vs {type.subtype}) "
                    f"and 'closed' ({self.closed} vs {type.closed}) attributes"
                )
        else:
            raise TypeError(
                f"Not supported to convert IntervalArray to '{type}' type"
            )

    return pyarrow.ExtensionArray.from_storage(interval_type, storage_array)

def queryables(self) -> dict[str, Any]:
    """return a dict of the kinds allowable columns for this object"""
    # mypy doesn't recognize DataFrame._AXIS_NAMES, so we re-write it here
    axis_names = {0: "index", 1: "columns"}

    # compute the values_axes queryables
    d1 = [(a.cname, a) for a in self.index_axes]
    d2 = [(axis_names[axis], None) for axis, values in self.non_index_axes]
    d3 = [
        (v.cname, v) for v in self.values_axes if v.name in set(self.data_columns)
    ]

    return dict(d1 + d2 + d3)

def median(self, *, axis: AxisInt | None = None, skipna: bool = True, **kwargs):
    nv.validate_median((), kwargs)

    if axis is not None and abs(axis) >= self.ndim:
        raise ValueError("abs(axis) must be less than ndim")

    result = nanops.nanmedian(self._ndarray, axis=axis, skipna=skipna)
    return self._wrap_reduction_result(axis, result)

def __iter__(self) -> Iterator:
    if self.ndim == 1:
        if not self._hasna:
            for val in self._data:
                yield val
        else:
            na_value = self.dtype.na_value
            for isna_, val in zip(self._mask, self._data, strict=True):
                if isna_:
                    yield na_value
                else:
                    yield val
    else:
        for i in range(len(self)):
            yield self[i]

def get_dtypes(self) -> npt.NDArray[np.object_]:
    cache = self._dtypes_cache
    if cache is None:
        blocks = self.blocks
        dtypes = np.array([blk.dtype for blk in blocks], dtype=object)
        cache = dtypes.take(self.blknos)
        # An invalidating write that landed while we computed has already
        # cleared the cache, so storing now would leave the stale array for good.
        if blocks is self.blocks:
            self._dtypes_cache = cache
    return cache.copy()

def dtype(self) -> tuple[DtypeKind, int, str, str]:
    dtype = self._col.dtype

    if isinstance(dtype, pd.CategoricalDtype):
        codes = self._col.values.codes
        (
            _,
            bitwidth,
            c_arrow_dtype_f_str,
            _,
        ) = self._dtype_from_pandasdtype(codes.dtype)
        return (
            DtypeKind.CATEGORICAL,
            bitwidth,
            c_arrow_dtype_f_str,
            Endianness.NATIVE,
        )
    elif is_string_dtype(dtype):
        if infer_dtype(self._col) in ("string", "empty"):
            return (
                DtypeKind.STRING,
                8,
                dtype_to_arrow_c_fmt(dtype),
                Endianness.NATIVE,
            )
        raise NotImplementedError("Non-string object dtypes are not supported yet")
    else:
        return self._dtype_from_pandasdtype(dtype)

def __from_arrow__(
    self, array: pyarrow.Array | pyarrow.ChunkedArray
) -> BooleanArray:
    """
    Construct BooleanArray from pyarrow Array/ChunkedArray.
    """
    import pyarrow

    if array.type != pyarrow.bool_() and not pyarrow.types.is_null(array.type):
        raise TypeError(f"Expected array of boolean type, got {array.type} instead")

    if isinstance(array, pyarrow.Array):
        chunks = [array]
        length = len(array)
    else:
        # pyarrow.ChunkedArray
        chunks = array.chunks
        length = array.length()

    if pyarrow.types.is_null(array.type):
        mask = np.ones(length, dtype=bool)
        # No need to init data, since all null
        data = np.empty(length, dtype=bool)
        return BooleanArray(data, mask)

    results = []
    for arr in chunks:
        buflist = arr.buffers()
        data = pyarrow.BooleanArray.from_buffers(
            arr.type, len(arr), [None, buflist[1]], offset=arr.offset
        ).to_numpy(zero_copy_only=False)
        if arr.null_count != 0:
            mask = pyarrow.BooleanArray.from_buffers(
                arr.type, len(arr), [None, buflist[0]], offset=arr.offset
            ).to_numpy(zero_copy_only=False)
            mask = ~mask
        else:
            mask = np.zeros(len(arr), dtype=bool)

        bool_arr = BooleanArray(data, mask)
        results.append(bool_arr)

    if not results:
        return BooleanArray(
            np.array([], dtype=np.bool_), np.array([], dtype=np.bool_)
        )
    else:
        return BooleanArray._concat_same_type(results)

def __call__(
    self,
    args: tuple[Any, ...],
    kwargs: dict[str, Any],
    fname: str | None = None,
    max_fname_arg_count: int | None = None,
    method: str | None = None,
) -> None:
    if not args and not kwargs:
        return None

    fname = self.fname if fname is None else fname
    max_fname_arg_count = (
        self.max_fname_arg_count
        if max_fname_arg_count is None
        else max_fname_arg_count
    )
    method = self.method if method is None else method

    if method == "args":
        validate_args(fname, args, cast("int", max_fname_arg_count), self.defaults)
    elif method == "kwargs":
        validate_kwargs(fname, kwargs, self.defaults)
    elif method == "both":
        validate_args_and_kwargs(
            fname, args, kwargs, cast("int", max_fname_arg_count), self.defaults
        )
    else:
        raise ValueError(f"invalid validation method '{method}'")

def _setitem_array(self, key, value) -> None:
    # also raises Exception if object array with NA values
    if com.is_bool_indexer(key):
        # bool indexer is indexing along rows
        if len(key) != len(self.index):
            raise ValueError(
                f"Item wrong length {len(key)} instead of {len(self.index)}!"
            )
        key = check_bool_indexer(self.index, key)
        indexer = key.nonzero()[0]
        if isinstance(value, DataFrame):
            # GH#39931 reindex since iloc does not align
            value = value.reindex(self.index.take(indexer))
        self.iloc[indexer] = value

    # Note: unlike self.iloc[:, indexer] = value, this will
    #  never try to overwrite values inplace

    elif isinstance(value, DataFrame):
        check_key_length(self.columns, key, value)
        for k1, k2 in zip(key, value.columns, strict=False):
            self[k1] = value[k2]

    elif not is_list_like(value):
        for col in key:
            self[col] = value

    elif isinstance(value, np.ndarray) and value.ndim == 2:
        self._iset_not_inplace(key, value)

    elif np.ndim(value) > 1:
        # list of lists
        value = DataFrame(value).values
        self._setitem_array(key, value)

    else:
        self._iset_not_inplace(key, value)

def equals(self, other: object) -> bool:
    """
    Implementation for DataFrame.equals
    """
    if not isinstance(other, type(self)):
        return False

    self_axes, other_axes = self.axes, other.axes
    if len(self_axes) != len(other_axes):
        return False
    if not all(
        ax1.equals(ax2) for ax1, ax2 in zip(self_axes, other_axes, strict=True)
    ):
        return False

    return self._equal_values(other)

def _maybe_cast_listlike_indexer(self, keyarr):
    """
    Analogue to maybe_cast_indexer for get_indexer instead of get_loc.
    """
    try:
        res = self._data._validate_listlike(keyarr, allow_object=True)
    except (ValueError, TypeError):
        if not isinstance(keyarr, ExtensionArray):
            # e.g. we don't want to cast DTA to ndarray[object]
            res = com.asarray_tuplesafe(keyarr)
            # TODO: com.asarray_tuplesafe shouldn't cast e.g. DatetimeArray
        else:
            res = keyarr
    return Index(res, dtype=res.dtype)

def delete(self, loc) -> Self:
    new_left: np.ndarray | DatetimeArray | TimedeltaArray
    new_right: np.ndarray | DatetimeArray | TimedeltaArray
    if isinstance(self._left, np.ndarray):
        new_left = np.delete(self._left, loc)
        assert isinstance(self._right, np.ndarray)
        new_right = np.delete(self._right, loc)
    else:
        new_left = self._left.delete(loc)
        assert not isinstance(self._right, np.ndarray)
        new_right = self._right.delete(loc)
    return self._shallow_copy(left=new_left, right=new_right)

def check_dtype_backend(dtype_backend: DtypeBackend | lib.NoDefault) -> None:
    if dtype_backend is not lib.no_default:
        if dtype_backend not in ["numpy_nullable", "pyarrow"]:
            raise ValueError(
                f"dtype_backend {dtype_backend} is invalid, only 'numpy_nullable' and "

def _get_axes(
    N: int, K: int, index: Index | None, columns: Index | None
) -> tuple[Index, Index]:
    # helper to create the axes as indexes
    # return axes or defaults

    if index is None:
        index = default_index(N)
    else:
        index = ensure_index(index)

    if columns is None:
        columns = default_index(K)
    else:
        columns = ensure_index(columns)
    return index, columns

def range_to_ndarray(rng: range) -> np.ndarray:
    """
    Cast a range object to ndarray.
    """
    # GH#30171 perf avoid realizing range as a list in np.array
    try:
        arr = np.arange(rng.start, rng.stop, rng.step, dtype="int64")
    except OverflowError:
        # GH#30173 handling for ranges that overflow int64
        if (rng.start >= 0 and rng.step > 0) or (rng.step < 0 <= rng.stop):
            try:
                arr = np.arange(rng.start, rng.stop, rng.step, dtype="uint64")
            except OverflowError:
                arr = construct_1d_object_array_from_listlike(list(rng))
        else:
            arr = construct_1d_object_array_from_listlike(list(rng))
    return arr

def _take_nd_ndarray(
    arr: np.ndarray,
    indexer: npt.NDArray[np.intp] | None,
    axis: AxisInt,
    fill_value,
    allow_fill: bool,
) -> np.ndarray:
    if indexer is None:
        indexer = np.arange(arr.shape[axis], dtype=np.intp)
        dtype, fill_value = arr.dtype, arr.dtype.type()
    else:
        indexer = ensure_platform_int(indexer)

    dtype, fill_value, mask_info = _take_preprocess_indexer_and_fill_value(
        arr, indexer, fill_value, allow_fill
    )

    flip_order = False
    if arr.ndim == 2 and arr.flags.f_contiguous:
        flip_order = True

    if flip_order:
        arr = arr.T
        axis = arr.ndim - axis - 1

    # at this point, it's guaranteed that dtype can hold both the arr values
    # and the fill_value
    out_shape_ = list(arr.shape)
    out_shape_[axis] = len(indexer)
    out_shape = tuple(out_shape_)
    if arr.flags.f_contiguous and axis == arr.ndim - 1:
        # minor tweak that can make an order-of-magnitude difference
        # for dataframes initialized directly from 2-d ndarrays
        # (s.t. df.values is c-contiguous and df._mgr.blocks[0] is its
        # f-contiguous transpose)
        out = np.empty(out_shape, dtype=dtype, order="F")
    else:
        out = np.empty(out_shape, dtype=dtype)

    func = _get_take_nd_function(
        arr.ndim, arr.dtype, out.dtype, axis=axis, mask_info=mask_info
    )
    if mask_info is not None:
        _, needs_fill = mask_info
    else:
        needs_fill = allow_fill
    func(arr, indexer, out, fill_value, allow_fill=needs_fill)

    if flip_order:
        out = out.T
    return out

def _set_default_format(self, vmin, vmax):
    """Returns the default ticks spacing."""
    info = self.finder(vmin, vmax, self.freq, self.anchor)

    if self.isminor:
        format = np.compress(info["min"] & np.logical_not(info["maj"]), info)
    else:
        format = np.compress(info["maj"], info)
    self.formatdict = {x: f for (x, _, _, f) in format}
    return self.formatdict

def _maybe_infer_ndim(
    values: ArrayLike, placement: BlockPlacement, ndim: int | None
) -> int:
    """
    If `ndim` is not provided, infer it from placement and values.
    """
    if ndim is None:
        # GH#38134 Block constructor now assumes ndim is not None
        if not isinstance(values.dtype, np.dtype):
            if len(placement) != 1:
                ndim = 1
            else:
                ndim = 2
        else:
            ndim = values.ndim
    return ndim

def _rank(
    self,
    *,
    axis: AxisInt = 0,
    method: RankMethod = "average",
    na_option: RankNaOption = "keep",
    ascending: bool = True,
    pct: bool = False,
):
    # GH#62043 Avoid going through copy-making ensure_data in algorithms.rank
    if axis != 0 or self.ndim != 1:
        raise NotImplementedError

    from pandas.core.arrays import FloatingArray

    data = self._data
    if data.dtype.kind == "b":
        data = data.view("uint8")

    result = libalgos.rank_1d(
        data,
        is_datetimelike=False,
        ties_method=method,
        ascending=ascending,
        na_option=na_option,
        pct=pct,
        mask=self.isna(),
    )
    if na_option in ["top", "bottom"]:
        mask = np.zeros(self.shape, dtype=bool)
    else:
        mask = self._mask.copy()

    if method != "average" and not pct:
        if na_option not in ["top", "bottom"]:
            result[self._mask] = 0  # avoid warning on casting
        result = result.astype("uint64", copy=False)
        from pandas.core.arrays import IntegerArray

        return IntegerArray(result, mask=mask)

    return FloatingArray(result, mask=mask)

def visit_Assign(self, node, **kwargs):
    """
    support a single assignment node, like

    c = a + b

    set the assigner at the top level, must be a Name node which
    might or might not exist in the resolvers

    """
    if len(node.targets) != 1:
        raise SyntaxError("can only assign a single expression")
    if not isinstance(node.targets[0], ast.Name):
        raise SyntaxError("left hand side of an assignment must be a single name")
    if self.env.target is None:
        raise ValueError("cannot assign without a target object")

    try:
        assigner = self.visit(node.targets[0], **kwargs)
    except UndefinedVariableError:
        assigner = node.targets[0].id

    self.assigner = getattr(assigner, "name", assigner)
    if self.assigner is None:
        raise SyntaxError(
            "left hand side of an assignment must be a single resolvable name"
        )

    return self.visit(node.value, **kwargs)

def _wrap_join_result(
    self,
    joined: ArrayLike,
    other: Self,
    lidx: npt.NDArray[np.intp] | None,
    ridx: npt.NDArray[np.intp] | None,
    how: JoinHow,
) -> tuple[Self, npt.NDArray[np.intp] | None, npt.NDArray[np.intp] | None]:
    assert other.dtype == self.dtype

    if lidx is not None and lib.is_range_indexer(lidx, len(self)):
        lidx = None
    if ridx is not None and lib.is_range_indexer(ridx, len(other)):
        ridx = None

    # return self or other if possible to maintain cached attributes
    if lidx is None:
        join_index = self
    elif ridx is None:
        join_index = other
    else:
        join_index = self._constructor._with_infer(
            joined, dtype=self.dtype, copy=False
        )

    names = other.names if how == "right" else self.names
    if join_index.names != names:
        join_index = join_index.set_names(names)

    return join_index, lidx, ridx

def _format_regular_rows(self) -> Iterable[ExcelCell]:
    if self._has_aliases or self.header:
        self.rowcounter += 1

    # output index and index_label?
    if self.index:
        # check aliases
        # if list only take first as this is not a MultiIndex
        if self.index_label and isinstance(
            self.index_label, (list, tuple, np.ndarray, Index)
        ):
            index_label = self.index_label[0]
        # if string good to go
        elif self.index_label and isinstance(self.index_label, str):
            index_label = self.index_label
        else:
            index_label = self.df.index.names[0]

        if isinstance(self.columns, MultiIndex):
            self.rowcounter += 1

        if index_label and self.header is not False:
            yield ExcelCell(self.rowcounter - 1, 0, index_label, None)

        # write index_values
        index_values = self.df.index
        if isinstance(self.df.index, PeriodIndex):
            index_values = self.df.index.to_timestamp()

        for idx, idxval in enumerate(index_values):
            yield CssExcelCell(
                row=self.rowcounter + idx,
                col=0,
                val=idxval,
                style=None,
                css_styles=getattr(self.styler, "ctx_index", None),
                css_row=idx,
                css_col=0,
                css_converter=self.style_converter,
            )
        coloffset = 1
    else:
        coloffset = 0

    yield from self._generate_body(coloffset)

def _is_shorthand_color(self, color_string: str) -> bool:
    """Check if color code is shorthand.

    #FFF is a shorthand as opposed to full #FFFFFF.
    """
    code = color_string.lstrip("#")
    if len(code) == 3:
        return True
    elif len(code) == 6:
        return False
    else:
        raise ValueError(f"Unexpected color {color_string}")

def _arith_method(self, other, op):
    op_name = op.__name__

    if isinstance(other, SparseArray):
        return _sparse_array_op(self, other, op, op_name)

    elif is_scalar(other):
        with np.errstate(all="ignore"):
            fill = op(_get_fill(self), np.asarray(other))
            result = op(self.sp_values, other)

        if op_name == "divmod":
            left, right = result
            lfill, rfill = fill
            return (
                _wrap_result(op_name, left, self.sp_index, lfill),
                _wrap_result(op_name, right, self.sp_index, rfill),
            )

        return _wrap_result(op_name, result, self.sp_index, fill)

    else:
        if not isinstance(
            other, (list, np.ndarray, ExtensionArray)
        ) and not ops.has_castable_attr(other):
            warnings.warn(
                f"Operation with {type(other).__name__} is deprecated. "
                "In a future version these will be treated as scalar-like. "
                "To retain the old behavior, explicitly wrap in a Series "
                "instead.",
                Pandas4Warning,
                stacklevel=find_stack_level(),
            )

        other = np.asarray(other)
        with np.errstate(all="ignore"):
            if len(self) != len(other):
                raise AssertionError(
                    f"length mismatch: {len(self)} vs. {len(other)}"
                )
            if not isinstance(other, SparseArray):
                dtype = getattr(other, "dtype", None)
                other = _as_sparse_operand(other, self.fill_value, dtype=dtype)
            return _sparse_array_op(self, other, op, op_name)

def _getitem_axis(self, key, axis: AxisInt):
    if key is Ellipsis:
        key = slice(None)
    elif isinstance(key, ABCDataFrame):
        raise IndexError(
            "DataFrame indexer is not allowed for .iloc\n"
            "Consider using .loc for automatic alignment."
        )

    if isinstance(key, slice):
        return self._get_slice_axis(key, axis=axis)

    if is_iterator(key):
        key = list(key)

    if isinstance(key, list):
        key = np.asarray(key)

    if com.is_bool_indexer(key):
        self._validate_key(key, axis)
        return self._getbool_axis(key, axis=axis)

    # a list of integers
    elif is_list_like_indexer(key):
        return self._get_list_axis(key, axis=axis)

    # a single integer
    else:
        key = item_from_zerodim(key)
        if not is_integer(key):
            raise TypeError("Cannot index by location index with a non-integer key")

        # validate the location
        self._validate_integer(key, axis)

        return self.obj._ixs(key, axis=axis)

def write_style(self) -> None:
    # We use the "scoped" attribute here so that the desired
    # style properties for the data frame are not then applied
    # throughout the entire notebook.
    template_first = """\
        <style scoped>"""
    template_last = """\
        </style>"""
    template_select = """\
            .dataframe %s {
                %s: %s;
            }"""
    element_props = [
        ("tbody tr th:only-of-type", "vertical-align", "middle"),
        ("tbody tr th", "vertical-align", "top"),
    ]
    if isinstance(self.columns, MultiIndex):
        element_props.append(("thead tr th", "text-align", "left"))
        if self.show_row_idx_names:
            element_props.append(
                ("thead tr:last-of-type th", "text-align", "right")
            )
    else:
        element_props.append(("thead th", "text-align", "right"))
    template_mid = "\n\n".join(template_select % t for t in element_props)
    template = dedent(f"{template_first}\n{template_mid}\n{template_last}")
    self.write(template)

def _update_stacker(cls, ax: Axes, stacking_id: int | None, values) -> None:
    if stacking_id is None:
        return
    if (values >= 0).all():
        # TODO #54485
        ax._stacker_pos_prior[stacking_id] += values  # type: ignore[attr-defined]
    elif (values <= 0).all():
        # TODO #54485
        ax._stacker_neg_prior[stacking_id] += values  # type: ignore[attr-defined]

def infer_filename(self) -> str | None:
    """
    If an explicit archive_name is not given, we still want the file inside the zip
    file not to be named something.tar, because that causes confusion (GH39465).
    """
    if self.name is None:
        return None

    filename = Path(self.name)
    if filename.suffix == ".tar":
        return filename.with_suffix("").name
    elif filename.suffix in (".tar.gz", ".tar.bz2", ".tar.xz"):
        return filename.with_suffix("").with_suffix("").name
    return filename.name

def isin(self, values: ArrayLike) -> npt.NDArray[np.bool_]:
    value_set = [
        pa_scalar.as_py()
        for pa_scalar in [pa.scalar(value, from_pandas=True) for value in values]
        if pa_scalar.type in (pa.string(), pa.null(), pa.large_string())
    ]

    # short-circuit to return all False array.
    if not value_set:
        return np.zeros(len(self), dtype=bool)

    result = pc.is_in(
        self._pa_array, value_set=pa.array(value_set, type=self._pa_array.type)
    )
    # pyarrow 2.0.0 returned nulls, so we explicitly specify dtype to convert nulls
    # to False
    return np.array(result, dtype=np.bool_)

def _chunk_to_dataframe(self) -> DataFrame:
    n = self._current_row_in_chunk_index
    m = self._current_row_in_file_index
    ix = range(m - n, m)
    rslt = {}

    js, jb = 0, 0
    infer_string = using_string_dtype()
    for j in range(self.column_count):
        name = self.column_names[j]

        if self._column_types[j] == b"d":
            col_arr = self._byte_chunk[jb, :].view(dtype=self.byte_order + "d")
            rslt[name] = pd.Series(col_arr, dtype=np.float64, index=ix, copy=False)
            convert_type = self._column_convert_types[j]
            if convert_type is not None:
                rslt[name] = _convert_datetimes(rslt[name], convert_type)
            jb += 1
        elif self._column_types[j] == b"s":
            if self._str_mode != const.string_mode_object:
                rslt[name] = pd.Series(
                    self._string_column(js), index=ix, copy=False
                )
            else:
                rslt[name] = pd.Series(
                    self._string_chunk[js, :], index=ix, copy=False
                )
                if self.convert_text and (self.encoding is not None):
                    rslt[name] = self._decode_string(rslt[name].str)
                    if infer_string:
                        rslt[name] = rslt[name].astype("str")

            js += 1
        else:
            self.close()
            raise ValueError(f"unknown column type {self._column_types[j]!r}")

    df = DataFrame(rslt, columns=self.column_names, index=ix, copy=False)
    return df

def _have_mi_columns(self) -> bool:
    if self.header is None:
        return False

    header = self.header
    if isinstance(header, (list, tuple, np.ndarray)):
        return len(header) > 1
    else:
        return False

def write(self, obj, data_columns=None, **kwargs) -> None:  # type: ignore[override]
    if data_columns is None:
        data_columns = []
    elif data_columns is True:
        data_columns = obj.columns.tolist()
    obj, self.levels = self.validate_multiindex(obj)
    assert isinstance(self.levels, list)  # for mypy
    for n in self.levels:
        if n not in data_columns:
            data_columns.insert(0, n)
    super().write(obj=obj, data_columns=data_columns, **kwargs)

def assert_class_equal(
    left: Any, right: Any, exact: bool | str = True, obj: str = "Input"
) -> None:
    """
    Checks classes are equal.
    """
    __tracebackhide__ = True

    def repr_class(x: Any) -> Any:
        if isinstance(x, Index):
            # return Index as it is to include values in the error message
            return x

        return type(x).__name__

    def is_class_equiv(idx: Index) -> bool:
        """Classes that are a RangeIndex (sub-)instance or exactly an `Index` .

        This only checks class equivalence. There is a separate check that the
        dtype is int64.
        """
        return type(idx) is Index or isinstance(idx, RangeIndex)

    if type(left) == type(right):
        return

    if exact == "equiv":
        if is_class_equiv(left) and is_class_equiv(right):
            return

    msg = f"{obj} classes are different"
    raise_assert_detail(obj, msg, repr_class(left), repr_class(right))

def _searchsorted_monotonic(self, label, side: Literal["left", "right"] = "left"):
    if (
        self.is_monotonic_increasing
        and isinstance(label, (Timestamp, Timedelta))
        and abbrev_to_npy_unit(label.unit) > abbrev_to_npy_unit(self.unit)
    ):
        # For non-matching units we can safely round down (with side=right)
        # This is needed for GH#63262
        if side == "right":
            label = label.as_unit(self.unit)  # this should always be a round-down
        else:
            # round up
            label = label.ceil(self.unit).as_unit(self.unit)

    return super()._searchsorted_monotonic(label, side)

def _parse_letter_version(
    letter: str | None, number: str | bytes | SupportsInt | None
) -> tuple[str, int] | None:
    if letter:
        # We consider there to be an implicit 0 in a pre-release if there is
        # not a numeral associated with it.
        if number is None:
            number = 0

        # We normalize any letters to their lower case form
        letter = letter.lower()

        # We consider some words to be alternate spellings of other words and
        # in those cases we want to normalize the spellings to our preferred
        # spelling.
        if letter == "alpha":
            letter = "a"
        elif letter == "beta":
            letter = "b"
        elif letter in ["c", "pre", "preview"]:
            letter = "rc"
        elif letter in ["rev", "r"]:
            letter = "post"

        return letter, int(number)
    if not letter and number:
        # We assume if we are given a number, but we are not given a letter
        # then this is using the implicit post release syntax (e.g. 1.0-1)
        letter = "post"

        return letter, int(number)

    return None

def __getitem__(self, key: int) -> Any:
    """Provide backward-compatible tuple-style access."""
    if key == 0:
        return self.column
    elif key == 1:
        return self.aggfunc
    elif key == 2:
        return self.args
    elif key == 3:
        return self.kwargs
    raise IndexError("index out of range")

def _check_compatible_with(
    self,
    #  error: Argument 1 of "_check_compatible_with" is incompatible with
    # supertype "pandas.core.arrays.datetimelike.DatetimeLikeArrayMixin";
    # supertype defines the argument type as "Period | Timestamp | Timedelta
    # | NaTType"
    other: Period | NaTType | PeriodArray,  # type: ignore[override]
) -> None:
    if other is NaT:
        return
    elif isinstance(other, Period):
        self._require_matching_unit(other._dtype._freqstr)
    else:
        # error: Item "NaTType" of "NaTType | PeriodArray" has no
        # attribute "freq"
        self._require_matching_unit(other.dtype._freqstr)  # type: ignore[union-attr]

def _get_block_for_concat_plan(
    mgr: BlockManager, bp: BlockPlacement, blkno: int, *, max_len: int
) -> Block:
    blk = mgr.blocks[blkno]
    # Assertions disabled for performance:
    #  assert bp.is_slice_like
    #  assert blkno != -1
    #  assert (mgr.blknos[bp] == blkno).all()

    if len(bp) == len(blk.mgr_locs) and (
        blk.mgr_locs.is_slice_like and blk.mgr_locs.as_slice.step == 1
    ):
        nb = blk
    else:
        ax0_blk_indexer = mgr.blklocs[bp.indexer]

        slc = lib.maybe_indices_to_slice(ax0_blk_indexer, max_len)
        # TODO: in all extant test cases 2023-04-08 we have a slice here.
        #  Will this always be the case?
        if isinstance(slc, slice):
            nb = blk.slice_block_columns(slc)
        else:
            nb = blk.take_block_columns(slc)

    # assert nb.shape == (len(bp), mgr.shape[1])
    return nb

def _getitem_bool_array(self, key):
    # also raises Exception if object array with NA values
    # warning here just in case -- previously __setitem__ was
    # reindexing but __getitem__ was not; it seems more reasonable to
    # go with the __setitem__ behavior since that is more consistent
    # with all other indexing behavior
    if isinstance(key, Series) and not key.index.equals(self.index):
        warnings.warn(
            "Boolean Series key will be reindexed to match DataFrame index.",
            UserWarning,
            stacklevel=find_stack_level(),
        )
    elif len(key) != len(self.index):
        raise ValueError(
            f"Item wrong length {len(key)} instead of {len(self.index)}."
        )

    # check_bool_indexer will throw exception if Series key cannot
    # be reindexed to match DataFrame rows
    key = check_bool_indexer(self.index, key)

    if key.all():
        return self.copy(deep=False)

    indexer = key.nonzero()[0]
    return self.take(indexer, axis=0)

def _na_value(self) -> Hashable:
    """The expected NA value to use with this index."""
    dtype = self.dtype
    if isinstance(dtype, np.dtype):
        if dtype.kind in "mM":
            return NaT
        return np.nan
    return dtype.na_value

def prune(self, klass):
    if self.op in ARITH_OPS_SYMS:
        # GH#41100: arithmetic in a where-clause is not supported. PyTables
        # support is in maintenance mode, so rather than grow the query
        # grammar we raise with a pointer to a working alternative.
        raise NotImplementedError(
            "arithmetic operations are not supported inside an HDFStore "
            "'where' filter; instead store a precomputed column as a "
            "data_column and query that, or read the data and apply the "
            "filter in pandas (e.g. df[df['A'] % 3 == 0])."
        )

    def pr(left, right):
        """create and return a new specialized BinOp from myself"""
        if left is None:
            return right
        elif right is None:
            return left

        k = klass
        if isinstance(left, ConditionBinOp):
            if isinstance(right, ConditionBinOp):
                k = JointConditionBinOp
            elif isinstance(left, k):
                return left
            elif isinstance(right, k):
                return right

        elif isinstance(left, FilterBinOp):
            if isinstance(right, FilterBinOp):
                k = JointFilterBinOp
            elif isinstance(left, k):
                return left
            elif isinstance(right, k):
                return right

        return k(
            self.op, left, right, queryables=self.queryables, encoding=self.encoding
        ).evaluate()

    left, right = self.lhs, self.rhs

    if is_term(left) and is_term(right):
        res = pr(left, right)
    elif not is_term(left) and is_term(right):
        res = pr(left.prune(klass), right)
    elif is_term(left) and not is_term(right):
        res = pr(left, right.prune(klass))
    elif not (is_term(left) or is_term(right)):
        res = pr(left.prune(klass), right.prune(klass))

    return res

def to_string(self) -> str:
    series = self.tr_series
    footer = self._get_footer()

    if len(series) == 0:
        return f"{type(self.series).__name__}([], {footer})"

    index = series.index
    have_header = _has_names(index)
    if isinstance(index, MultiIndex):
        fmt_index = index._format_multi(include_names=True, sparsify=None)
        adj = printing.get_adjustment()
        fmt_index = adj.adjoin(2, *fmt_index).split("\n")
    else:
        fmt_index = index._format_flat(include_name=True)
    fmt_values = self._get_formatted_values()

    if self.is_truncated_vertically:
        n_header_rows = 0
        row_num = self.tr_row_num
        row_num = cast("int", row_num)
        width = self.adj.len(fmt_values[row_num - 1])
        if width > 3:
            dot_str = "..."
        else:
            dot_str = ".."
        # Series uses mode=center because it has single value columns
        # DataFrame uses mode=left
        dot_str = self.adj.justify([dot_str], width, mode="center")[0]
        fmt_values.insert(row_num + n_header_rows, dot_str)
        fmt_index.insert(row_num + 1, "")

    if self.index:
        result = self.adj.adjoin(3, *[fmt_index[1:], fmt_values])
    else:
        result = self.adj.adjoin(3, fmt_values)

    if self.header and have_header:
        result = fmt_index[0] + "\n" + result

    if footer:
        result += "\n" + footer

    return str("".join(result))

def _str_rsplit(self, pat: str | None = None, n: int | None = -1) -> Self:
    if pat is not None and not isinstance(pat, str):
        msg = f"expected a string object, not {type(pat).__name__}"
        raise TypeError(msg)
    if n in {-1, 0}:
        n = None
    if pat is None:
        return self._from_pyarrow_array(
            pc.utf8_split_whitespace(self._pa_array, max_splits=n, reverse=True)
        )
    return self._from_pyarrow_array(
        pc.split_pattern(self._pa_array, pat, max_splits=n, reverse=True)

def _normalize_stop_mode(mode: _StopMode, *, allow_force: bool = True) -> _StopMode:
    if mode not in _STOP_MODE_PRIORITY:
        raise ValueError(
            f"Unknown stop mode {mode!r}. Expected one of: graceful, fast, force"
        )
    if mode == "force" and not allow_force:
        raise ValueError("The force stop mode is not supported in this context")
    return mode

def _getarg(
    request: Request, name: bytes, default: Any = None, type_: type = str
) -> Any:
    assert request.args is not None
    return type_(request.args[name][0]) if name in request.args else default

def process_options(self, args: list[str], opts: argparse.Namespace) -> None:
    super().process_options(args, opts)
    try:
        opts.spargs = arglist_to_dict(opts.spargs)
    except ValueError:
        raise UsageError(
            "Invalid -a value, use -a NAME=VALUE", print_help=False
        ) from None
    if opts.output or opts.overwrite_output:
        assert self.settings is not None
        feeds = feed_process_params_from_cli(
            self.settings,
            opts.output,
            overwrite_output=opts.overwrite_output,
        )
        self.settings.set("FEEDS", feeds, priority="cmdline")

def _update_curprio(self) -> None:
    prios = {
        p
        for queues in (self.queues, self._start_queues)
        for p, q in queues.items()
        if q
    }
    self.curprio = min(prios) if prios else None

def matches(self, url: str) -> bool:
    if self.allow_domains and not url_is_from_any_domain(url, self.allow_domains):
        return False
    if self.deny_domains and url_is_from_any_domain(url, self.deny_domains):
        return False

    allowed = (
        (regex.search(url) for regex in self.allow_res)
        if self.allow_res
        else [True]
    )
    denied = (regex.search(url) for regex in self.deny_res) if self.deny_res else ()
    return any(allowed) and not any(denied)

def _set_conditional_validators(
    self, request: Request, cachedresponse: Response
) -> None:
    if b"Last-Modified" in cachedresponse.headers:
        request.headers[b"If-Modified-Since"] = cachedresponse.headers[
            b"Last-Modified"
        ]

    if b"ETag" in cachedresponse.headers:
        request.headers[b"If-None-Match"] = cachedresponse.headers[b"ETag"]

def replace(
    self, *args: Any, cls: type[Request] | None = None, **kwargs: Any
) -> Request:
    body_passed = kwargs.get("body") is not None
    data: Any = kwargs.pop("data", None)
    data_passed: bool = data is not None

    if body_passed and data_passed:
        warnings.warn(
            "Both body and data passed. data will be ignored", stacklevel=2
        )
    elif not body_passed and data_passed:
        kwargs["body"] = self._dumps(data)

    return super().replace(*args, cls=cls, **kwargs)

async def _process_request(
    self,
    request: Request,
    download_func: Callable[[Request], Coroutine[Any, Any, Response]],
) -> Response | Request:
    for method in self.methods["process_request"]:
        assert method is not None
        response = await ensure_awaitable(
            self._handle_mw_method(method, request=request),
            _warn=global_object_name(method),
        )
        if response is not None and not isinstance(response, (Response, Request)):
            raise _InvalidOutput(
                f"Middleware {method.__qualname__} must return None, Response or "
                f"Request, got {response.__class__.__name__}"
            )
        if response:
            return response
    return await download_func(request)

def __init__(
    self, *args: Any, dumps_kwargs: dict[str, Any] | None = None, **kwargs: Any
) -> None:
    dumps_kwargs = copy.deepcopy(dumps_kwargs) if dumps_kwargs is not None else {}
    dumps_kwargs.setdefault("sort_keys", True)
    self._dumps_kwargs: dict[str, Any] = dumps_kwargs

    body_passed = kwargs.get("body") is not None
    data: Any = kwargs.pop("data", None)
    data_passed: bool = data is not None

    if body_passed and data_passed:
        warnings.warn(
            "Both body and data passed. data will be ignored", stacklevel=2
        )
    elif not body_passed and data_passed:
        kwargs["body"] = self._dumps(data)
        if "method" not in kwargs:
            kwargs["method"] = "POST"

    super().__init__(*args, **kwargs)
    self.headers.setdefault("Content-Type", "application/json")
    self.headers.setdefault(
        "Accept", "application/json, text/javascript, */*; q=0.01"

def check_stop_download(
    signal: object, crawler: Crawler, request: Request, **kwargs: Any
) -> StopDownload | None:
    """Send the given signal and check if any of its handlers raised
    :exc:`~scrapy.exceptions.StopDownload`.

    Return the raised exception or ``None``.
    """
    signal_result = crawler.signals.send_catch_log(
        signal=signal,
        request=request,
        spider=crawler.spider,
        **kwargs,
    )
    for handler, result in signal_result:
        if isinstance(result, Failure) and isinstance(result.value, StopDownload):
            logger.debug(
                f"Download stopped for {request} from signal handler {handler.__qualname__}"
            )
            return result.value

    return None

def start_parsing(self, url: str, opts: argparse.Namespace) -> None:
    assert self.crawler_process
    assert self.spidercls
    self.pcrawler = self._create_crawler(self.spidercls)
    self.crawler_process.crawl(self.pcrawler, **opts.spargs)
    self.crawler_process.start()
    if self.crawler_process.bootstrap_failed:
        self.exitcode = 1

    if not self.first_response:
        logger.error("No response downloaded for: %(url)s", {"url": url})

def closest_scrapy_cfg(
    path: str | os.PathLike[str] = ".",
    prevpath: str | os.PathLike[str] | None = None,
) -> str:
    """Return the path to the closest scrapy.cfg file by traversing the current
    directory and its parents
    """
    if prevpath is not None and str(path) == str(prevpath):
        return ""
    path = Path(path).resolve()
    cfgfile = path / "scrapy.cfg"
    if cfgfile.exists():
        return str(cfgfile)
    return closest_scrapy_cfg(path.parent, path)

def _print_commands(settings: BaseSettings, inproject: bool) -> None:
    _print_header(settings, inproject)
    print(
        "Usage:\n",
        "  scrapy <command> [options] [args]\n",
        "Available commands:\n",
    )
    cmds = _get_commands_dict(settings, inproject)
    print(
        "\n".join(
            f"  {cmdname:<13} {cmdclass.short_desc()}"
            for cmdname, cmdclass in sorted(cmds.items())
        )
    )
    if not inproject:
        print(
            "\n",
            "  [ more ]      More commands available when run from project directory",
        )
    print("\n", 'Use "scrapy <command> -h" to see more info about a command')

def _slot_gc(self, age: float = 60) -> None:
    mintime = monotonic() - age
    for key, slot in list(self.slots.items()):
        if not slot.active and slot.lastseen + slot.delay <= mintime:
            self.slots.pop(key).close()

def _get_method(method: _CallableT | str | None, spider: Spider) -> _CallableT | None:
    if callable(method):
        return method
    if isinstance(method, str):
        return getattr(spider, method, None)
    return None

def init_prios(self, startprios: Iterable[int]) -> None:
    if not startprios:
        return

    for priority in startprios:
        q = self.qfactory(priority)
        if q:
            self.queues[priority] = q
        else:
            q.close()
            self.changed = True
        if self._start_queue_cls:
            q = self._sqfactory(priority)
            if q:
                self._start_queues[priority] = q
            else:
                q.close()
                self.changed = True

    self.curprio = min(startprios)

def get_help(self) -> str:
    b = []
    b.append("Available Scrapy objects:")
    b.append(
        "  scrapy     scrapy module (contains scrapy.Request, scrapy.Selector, etc)"
    )
    for k, v in sorted(self.vars.items()):
        if self._is_relevant(v):
            b.append(f"  {k:<10} {v}")
    b.append("Useful shortcuts:")
    if self.fetch_available:
        b.append(
            "  fetch(url[, redirect=True]) "
            "Fetch URL and update local objects (by default, redirects are followed)"
        )
        b.append(
            "  fetch(req)                  "
            "Fetch a scrapy.Request and update local objects "
        )
    b.append("  shelp()           Shell help (print this help)")
    b.append("  view(response)    View response in a browser")

    return "\n".join(f"[s] {line}" for line in b) + "\n"

def _get_formatter(handler: logging.Handler, settings: Settings) -> logging.Formatter:
    fmt = settings.get("LOG_FORMAT")
    datefmt = settings.get("LOG_DATEFORMAT")
    if (
        isinstance(handler, logging.StreamHandler)
        and not isinstance(handler, logging.FileHandler)
        and settings.getbool("LOG_COLOR")
        and handler.stream.isatty()
        and tty_supports_color()
    ):
        try:
            from colorlog import ColoredFormatter  # noqa: PLC0415
        except ImportError:
            pass
        else:
            return ColoredFormatter(fmt=f"%(log_color)s{fmt}", datefmt=datefmt)
    return logging.Formatter(fmt=fmt, datefmt=datefmt)

def window_updated(self, event: WindowUpdated) -> None:
    if event.stream_id != 0:
        self.streams[event.stream_id].receive_window_update()
    else:
        # Send leftover data for all the streams
        for stream in self.streams.values():
            stream.receive_window_update()

def spider_closed(self, spider: Spider, reason: str) -> None:
    if self.task and self.task.running:
        self.task.stop()

    rpm_final, ipm_final = self.calculate_final_stats(spider)
    self.stats.set_value("responses_per_minute", rpm_final)
    self.stats.set_value("items_per_minute", ipm_final)

def _get_request_cookies(
    self, jar: CookieJar, request: Request
) -> Sequence[Cookie]:
    """
    Extract cookies from the Request.cookies attribute
    """
    if not request.cookies:
        return ()
    cookies: Iterable[VerboseCookie] = _to_verbose_cookies(request.cookies)
    for cookie in cookies:
        cookie.setdefault("secure", urlparse_cached(request).scheme == "https")
    formatted = filter(None, (self._format_cookie(c, request) for c in cookies))
    response = Response(request.url, headers={"Set-Cookie": formatted})
    return jar.make_cookies(response, request)

def to_bytes(
    text: str | bytes, encoding: str | None = None, errors: str = "strict"
) -> bytes:
    """Return the binary representation of ``text``. If ``text``
    is already a bytes object, return it as-is."""
    if isinstance(text, bytes):
        return text
    if not isinstance(text, str):
        raise TypeError(
            f"to_bytes must receive a str or bytes object, got {type(text).__name__}"
        )
    if encoding is None:
        encoding = "utf-8"
    return text.encode(encoding, errors)

def item_completed(
    self, results: list[FileInfoOrError], item: Any, info: MediaPipeline.SpiderInfo
) -> Any:
    with suppress(KeyError):
        ItemAdapter(item)[self.images_result_field] = [x for ok, x in results if ok]
    return item

def _collect(result: Any) -> list[Any]:
    if isinstance(result, (AsyncGenerator, CoroutineType)):
        if isinstance(result, CoroutineType):
            result.close()
        raise TypeError(
            "Callbacks that return a coroutine or an asynchronous generator "
            "must be defined with async def to be supported by contracts."
        )
    return list(arg_to_iter(result))

def _chunk_iter(
    text: str, chunk_size: int
) -> Iterable[tuple[str, int]]:  # pragma: no cover
    offset = len(text)
    while True:
        offset -= chunk_size * 1024
        if offset <= 0:
            break
        yield (text[offset:], offset)
    yield (text, 0)

def __init__(
    self,
    response: TextResponse | None = None,
    text: str | None = None,
    type: SelectorType | None = None,  # noqa: A002
    root: Any | None = _NOT_SET,
    **kwargs: Any,
):
    if response is not None and text is not None:
        raise ValueError(
            f"{self.__class__.__name__}.__init__() received both response and text"
        )

    # Any other response, e.g. a plain-text one, keeps type unset, so that
    # parsel determines it from the body.
    if type is None and root is _NOT_SET:
        if isinstance(response, XmlResponse):
            type = "xml"  # noqa: A001
        elif isinstance(response, JsonResponse):
            type = "json"  # noqa: A001
        elif response is None or isinstance(response, HtmlResponse):
            type = "html"  # noqa: A001

    if text is not None:
        response = _response_from_text(text, type)

    if response is not None:
        # parsel only treats bytes and text equivalently for "html" and
        # "xml", and treats an empty body as absent, unlike empty text.
        if PARSEL_BODY_ENCODING_FIXED and type in ("html", "xml") and response.body:
            encoding = response.encoding
            # None means the encoding was declared, not inferred from
            # the body, so the body hasn't been decoded as a side effect.
            if response._cached_ubody is None:
                kwargs["body"] = response.body
                kwargs["encoding"] = encoding
                text = None
            else:
                text = response.text
        else:
            text = response.text
        kwargs.setdefault("base_url", get_base_url(response))

    self.response = response

    if root is not _NOT_SET:
        kwargs["root"] = root

    super().__init__(text=text, type=type, **kwargs)

def _link_allowed(self, link: Link) -> bool:
    parsed_url = urlparse(link.url)
    if self.schemes and parsed_url.scheme not in self.schemes:
        return False
    if self.allow_res and not _matches(link.url, self.allow_res):
        return False
    if self.deny_res and _matches(link.url, self.deny_res):
        return False
    if self.allow_domains and not url_is_from_any_domain(
        parsed_url, self.allow_domains
    ):
        return False
    if self.deny_domains and url_is_from_any_domain(parsed_url, self.deny_domains):
        return False
    if self.deny_extensions and url_has_any_extension(
        parsed_url, self.deny_extensions
    ):
        return False
    return not self.restrict_text or _matches(link.text, self.restrict_text)

def _handle_downloader_output(
    self, result: Request | Response | Failure, request: Request
) -> Generator[Deferred[Any], Any, None]:
    if (
        isinstance(result, Failure)
        and self._stop_mode == "fast"
        and result.check(
            DownloadCancelledError,
            CancelledError,
            asyncio.exceptions.CancelledError,
        )
    ):
        return

    # downloader middleware can return requests (for example, redirects)
    if isinstance(result, Request):
        self.crawl(result)
        return

    try:
        yield self.scraper.enqueue_scrape(result, request)
    except Exception:
        assert self.spider is not None
        logger.exception(
            "Error while enqueuing scrape", extra={"spider": self.spider}

def _url_from_selector(sel: parsel.Selector) -> str:
    if isinstance(sel.root, str):
        # e.g. ::attr(href) result
        return strip_html5_whitespace(sel.root)
    if not hasattr(sel.root, "tag"):
        raise _InvalidSelector(f"Unsupported selector: {sel}")
    if sel.root.tag not in {"a", "link"}:
        raise _InvalidSelector(
            f"Only <a> and <link> elements are supported; got <{sel.root.tag}>"
        )
    href = sel.root.get("href")
    if href is None:
        raise _InvalidSelector(f"<{sel.root.tag}> element has no href attribute: {sel}")
    return strip_html5_whitespace(href)

def _deps(tox_ini: str, name: str) -> list[str]:
    block = re.search(
        r"^deps =\n((?:[ \t]+.*\n)*)", _section(tox_ini, name)[1], re.MULTILINE
    )
    if not block:
        return []
    deps = (re.sub(r"\s*#.*", "", line).strip() for line in block[1].splitlines())
    return [dep for dep in deps if dep]

def __next__(self) -> Deferred[Any]:
    # This puts a new Deferred into self.waiting_deferreds and returns it.
    # It also calls __anext__() if needed.
    if self.finished:
        raise StopIteration
    d: Deferred[Any] = Deferred()
    self.waiting_deferreds.append(d)
    if not self.anext_deferred:
        self._call_anext()
    return d

def from_spider(self, spider: Spider, results: TestResult) -> list[Request]:
    requests: list[Request] = []
    for method in self.tested_methods_from_spidercls(type(spider)):
        bound_method = getattr(spider, method)
        try:
            requests.extend(self.from_method(bound_method, results))
        except Exception:
            case = _create_testcase(bound_method, "contract")
            results.addError(case, sys.exc_info())

    return requests

def from_body(self, body: bytes) -> type[Response]:
    """Try to guess the appropriate response based on the body content.
    This method is a bit magic and could be improved in the future, but
    it's not meant to be used except for special cases where response types
    cannot be guess using more straightforward methods."""
    chunk = body[:5000]
    chunk = to_bytes(chunk)
    if not binary_is_text(chunk):
        return self.from_mimetype("application/octet-stream")
    lowercase_chunk = chunk.lower()
    if b"<html>" in lowercase_chunk:
        return self.from_mimetype("text/html")
    if b"<?xml" in lowercase_chunk:
        return self.from_mimetype("text/xml")
    if b"<!doctype html>" in lowercase_chunk:
        return self.from_mimetype("text/html")
    return self.from_mimetype("text")

async def process_item(self, item: Any, spider: Spider | None = None) -> Any:
    info = self.spiderinfo
    requests = arg_to_iter(self.get_media_requests(item, info))
    coros = [self._process_request(r, info, item) for r in requests]
    results: list[FileInfoOrError] = []
    if coros:
        if is_asyncio_available():
            results_asyncio = await asyncio.gather(*coros, return_exceptions=True)
            for res in results_asyncio:
                if isinstance(res, BaseException):
                    results.append((False, Failure(res)))
                else:
                    results.append((True, res))
        else:
            results = await cast(
                "Deferred[list[FileInfoOrError]]",
                DeferredList(
                    (deferred_from_coro(coro) for coro in coros), consumeErrors=True
                ),
            )
    return self.item_completed(results, item, info)

def _force_stop(self) -> None:
    if self.settings.getbool("TWISTED_REACTOR_ENABLED"):
        self._stop_reactor()
        return

    if (loop := self._reactorless_loop) is None:
        return
    if (task := self._reactorless_main_task) is not None:
        loop.call_soon_threadsafe(task.cancel)

def _parse_cachecontrol(self, r: Request | Response) -> dict[bytes, bytes | None]:
    if r not in self._cc_parsed:
        cch = r.headers.get(b"Cache-Control", b"")
        assert cch is not None
        parsed = parse_cachecontrol(cch)
        if isinstance(r, Response):
            for key in self.ignore_response_cache_controls:
                parsed.pop(key, None)
        self._cc_parsed[r] = parsed
    return self._cc_parsed[r]

def decode_robotstxt(
    robotstxt_body: bytes, spider: Spider | None, to_native_str_type: bool = False
) -> str:
    try:
        if to_native_str_type:
            body_decoded = to_unicode(robotstxt_body)
        else:
            body_decoded = robotstxt_body.decode("utf-8-sig", errors="ignore")
    except UnicodeDecodeError:
        # If we found garbage or robots.txt in an encoding other than UTF-8, disregard it.
        # Switch to 'allow all' state.
        logger.warning(
            "Failure while parsing robots.txt. File either contains garbage or "
            "is in an encoding other than UTF-8, treating it as an empty file.",
            exc_info=sys.exc_info(),
            extra={"spider": spider},
        )
        body_decoded = ""
    return body_decoded

def _exporter_supported(self, format_: str) -> bool:
    if format_ in self.exporters:
        return True
    if format_:
        logger.error("Unknown feed format: %(format)s", {"format": format_})
    else:
        logger.error(
            "Feed format not set and it could not be inferred from the "
            "feed URI; set it explicitly with the 'format' key"
        )
    return False

def deferred_from_coro(o: Awaitable[_T] | _T2) -> Deferred[_T] | _T2:
    """Convert a coroutine or other awaitable object into a Deferred,
    or return the object as is if it isn't a coroutine."""
    if isinstance(o, Deferred):
        return o
    if inspect.isawaitable(o):
        if not is_asyncio_available():
            # wrapping the coroutine directly into a Deferred, this doesn't work correctly with coroutines
            # that use asyncio, e.g. "await asyncio.sleep(1)"
            return Deferred.fromCoroutine(cast("Coroutine[Deferred[Any], Any, _T]", o))
        # wrapping the coroutine into a Future and then into a Deferred, this requires AsyncioSelectorReactor
        return Deferred.fromFuture(asyncio.ensure_future(o))
    return o

def get_reactor_settings() -> dict[str, Any]:
    """Return a settings dict that works with the installed reactor.

    ``Crawler._apply_settings()`` checks that the installed reactor matches the
    settings, so tests that run the crawler in the current process may need to
    pass a correct :setting:`TWISTED_REACTOR` setting value when creating it.
    """
    settings: dict[str, Any] = {}
    if is_reactor_installed():
        if not _is_asyncio_reactor_installed():
            settings["TWISTED_REACTOR"] = None
    else:
        # We are either running Scrapy tests for the reactorless mode, or
        # running some 3rd-party library tests for the reactorless mode, or
        # running some 3rd-party library tests without initializing a reactor
        # properly. The first two cases are fine, but we cannot distinguish the
        # last one from them.
        settings["TWISTED_REACTOR_ENABLED"] = False
        settings["DOWNLOAD_HANDLERS"] = {
            "ftp": None,
            "http": "scrapy.core.downloader.handlers._aiohttp.AiohttpDownloadHandler",
            "https": "scrapy.core.downloader.handlers._aiohttp.AiohttpDownloadHandler",
        }
    return settings

def get_callback_from_rules(
    self, spider: Spider, response: Response
) -> CallbackT | str | None:
    if getattr(spider, "rules", None):
        for rule in spider.rules:  # type: ignore[attr-defined]
            if rule.link_extractor.matches(response.url):
                return rule.callback or "parse"
    else:
        logger.error(
            "No CrawlSpider rules found in spider %(spider)r, "
            "please specify a callback to use for parsing",
            {"spider": spider.name},
        )
    return None

def is_cached_response_fresh(
    self, cachedresponse: Response, request: Request
) -> bool:
    cc = self._parse_cachecontrol(cachedresponse)
    ccreq = self._parse_cachecontrol(request)
    if b"no-cache" in cc or b"no-cache" in ccreq:
        return False

    now = time()
    freshnesslifetime = self._compute_freshness_lifetime(
        cachedresponse, request, now
    )
    currentage = self._compute_current_age(cachedresponse, request, now)

    reqmaxage = self._get_max_age(ccreq)
    if reqmaxage is not None:
        freshnesslifetime = min(freshnesslifetime, reqmaxage)

    if currentage < freshnesslifetime:
        return True

    if b"max-stale" in ccreq and b"must-revalidate" not in cc:
        # From RFC2616: "Indicates that the client is willing to
        # accept a response that has exceeded its expiration time.
        # If max-stale is assigned a value, then the client is
        # willing to accept a response that has exceeded its
        # expiration time by no more than the specified number of
        # seconds. If no value is assigned to max-stale, then the
        # client is willing to accept a stale response of any age."
        staleage = ccreq[b"max-stale"]
        if staleage is None:
            return True

        try:
            if currentage < freshnesslifetime + max(0, int(staleage)):
                return True
        except ValueError:
            pass

    # Cached response is stale, try to set validators if any
    self._set_conditional_validators(request, cachedresponse)
    return False

def _schedule_reactorless_shutdown(self, *, mode: _StopMode, signum: int) -> None:
    if (loop := self._reactorless_loop) is None:
        return

    log_func = self._log_fast_shutdown if mode == "fast" else self._log_shutdown
    loop.call_soon_threadsafe(log_func, signum)

    def _create_shutdown_task() -> None:
        coro = self._shutdown_reactorless(mode=mode)
        try:
            loop.create_task(coro)
        except RuntimeError:
            coro.close()

    loop.call_soon_threadsafe(_create_shutdown_task)

def sitemap_urls_from_robots(
    robots_text: str | bytes,
    base_url: str | None = None,
) -> Iterable[str]:
    if isinstance(robots_text, bytes):
        for line in BytesIO(robots_text):
            if line.lstrip()[:8].lower() == b"sitemap:":
                try:
                    url = line.partition(b":")[2].strip().decode()
                except UnicodeDecodeError:
                    continue
                yield urljoin(base_url or "", url)

    else:
        warnings.warn(
            "Passing `str` type as `robots_text` is deprecated, use `bytes`",
            ScrapyDeprecationWarning,
            stacklevel=2,
        )
        yield from _sitemap_urls_from_robots_str(robots_text, base_url)

async def stop_async(self, *, mode: _StopMode = "graceful") -> None:
    """Start a graceful stop of the crawler and complete when the crawler is stopped.

    .. versionadded:: 2.14
    """
    mode = _normalize_stop_mode(mode)
    was_crawling = self.crawling
    self.crawling = False

    if not was_crawling and mode == "graceful":
        return

    if mode == "force":
        if self._force_stop_callback is not None:
            await ensure_awaitable(self._force_stop_callback())
            return
        logger.warning(
            "Force stop requested, but no process-level force stop callback is available. Falling back to fast stop."
        )
        mode = "fast"

    if self._engine is None:
        return

    # During shutdown callbacks, graceful stop may be re-entered after
    # the engine has already switched to non-running state.
    if mode == "graceful" and not self._engine.running:
        return

    try:
        await self._engine.stop_async(mode=mode)
    except RuntimeError as exc:
        if str(exc) != "Engine not running":
            raise

def _embed_standard_shell(
    namespace: dict[str, Any] | None = None, banner: str = ""
) -> EmbedFuncT:
    """Start a standard python shell"""
    try:  # readline module is only available on unix systems
        import readline  # noqa: PLC0415
    except ImportError:
        pass
    else:
        import rlcompleter  # noqa: F401,PLC0415

        readline.parse_and_bind("tab:complete")  # type: ignore[attr-defined,unused-ignore]

    @wraps(_embed_standard_shell)
    def wrapper(namespace: dict[str, Any] = namespace or {}, banner: str = "") -> None:
        code.interact(banner=banner, local=namespace)

    return wrapper

def close_connections(self) -> None:
    """Close all the HTTP/2 connections and remove them from pool."""
    for conn in self._connections.values():
        assert conn.transport is not None  # typing
        conn.transport.abortConnection()

def open(self, spider: Spider) -> IO[bytes]:
    path = spider.crawler.settings["FEED_TEMPDIR"]
    if path and not Path(path).is_dir():
        raise OSError("Not a Directory: " + str(path))

    return NamedTemporaryFile(prefix="feed-", dir=path)

def process_spider_output(
    self,
    response: Response | None,
    result: Iterable[Any],
    spider: Spider | None = None,
) -> Iterable[Any]:
    for o in result:
        if (o := self._get_processed(o, response)) is not None:
            yield o

def set_environ(**kwargs: str) -> Iterator[None]:
    """Temporarily set environment variables inside the context manager and
    fully restore previous environment afterwards
    """

    original_env = {k: os.environ.get(k) for k in kwargs}
    os.environ.update(kwargs)
    try:
        yield
    finally:
        for k, v in original_env.items():
            if v is None:
                del os.environ[k]
            else:
                os.environ[k] = v

def __init__(self, uri: str, *, feed_options: dict[str, Any] | None = None):
    self.path: str = file_uri_to_path(uri) if uri.startswith("file:") else uri
    feed_options = feed_options or {}
    self.write_mode: OpenBinaryMode = (
        "wb" if feed_options.get("overwrite", False) else "ab"

def print_requests(self, lvl: int | None = None, colour: bool = True) -> None:
    if lvl is not None:
        requests = self.requests.get(lvl, [])
    elif self.requests:
        requests = self.requests[max(self.requests)]
    else:
        requests = []

    print("# Requests ", "-" * 65)
    _colorize.pprint(requests, colorize=colour)

def _iter_command_classes(module_name: str) -> Iterable[type[ScrapyCommand]]:
    # TODO: add `name` attribute to commands and merge this function with
    # scrapy.utils.spider.iter_spider_classes
    for module in walk_modules_iter(module_name):
        for obj in vars(module).values():
            if (
                inspect.isclass(obj)
                and issubclass(obj, ScrapyCommand)
                and obj.__module__ == module.__name__
                and obj not in {ScrapyCommand, BaseRunSpiderCommand}
            ):
                yield obj

def spider_closed(self, spider: Spider) -> None:
    if self.jobdir:
        with Path(self.statefn).open("wb") as f:
            assert hasattr(spider, "state")  # set in spider_opened
            pickle.dump(spider.state, f, protocol=4)

def get_shell_embed_func(
    shells: Iterable[str] | None = None, known_shells: KnownShellsT | None = None
) -> EmbedFuncT | None:
    """Return the first acceptable shell-embed function
    from a given list of shell names.
    """
    if shells is None:  # list, preference order of shells
        shells = DEFAULT_PYTHON_SHELLS.keys()
    if known_shells is None:  # available embeddable shells
        known_shells = DEFAULT_PYTHON_SHELLS.copy()
    for shell in shells:
        if shell in known_shells:
            try:
                # function test: run all setup code (imports),
                # but dont fall into the shell
                return known_shells[shell]()
            except ImportError:
                continue
    return None

def get_processed_request(
    self, request: Request, response: Response | None
) -> Request | None:
    if response is None:
        # start requests
        return request
    referrer = self.policy(response, request).referrer(response.url, request.url)
    if referrer is not None:
        request.headers.setdefault("Referer", referrer)
    return request

def _requirements(tox_ini: str, name: str) -> list[str]:
    requirements = []
    for dep in _deps(tox_ini, name):
        if match := re.fullmatch(r"\{\[(.+)\]deps\}", dep):
            requirements += _requirements(tox_ini, match[1])
        else:
            requirements.append(dep)
    return requirements

def _requests_to_follow(self, response: Response) -> Iterable[Request | None]:
    if not isinstance(response, HtmlResponse):
        return
    seen: set[Link] = set()
    response_rule_name = (
        response.request.meta.get("rule_name") if response.request else None
    )
    for rule_index, rule in enumerate(self._rules):
        if (
            rule.from_rules is not None
            and response_rule_name not in rule.from_rules
        ):
            continue
        links: list[Link] = [
            lnk
            for lnk in rule.link_extractor.extract_links(response)
            if lnk not in seen
        ]
        for link in cast("ProcessLinksT", rule.process_links)(links):
            seen.add(link)
            request = self._build_request(rule_index, link)
            yield cast("ProcessRequestT", rule.process_request)(request, response)

def post_process(self, output: list[Any]) -> None:
    for x in output:
        if is_item(x):
            missing = [arg for arg in self.args if arg not in ItemAdapter(x)]
            if missing:
                missing_fields = ", ".join(missing)
                raise ContractFail(f"Missing fields: {missing_fields}")

def create_crawler(
    self, crawler_or_spidercls: type[Spider] | str | Crawler
) -> Crawler:
    crawler = super().create_crawler(crawler_or_spidercls)
    if self._reactor_crawler is None:
        self._reactor_crawler = crawler
    else:
        ignored = [
            setting
            for setting in _REACTOR_SETTINGS
            if self._reactor_crawler.settings[setting] != crawler.settings[setting]
        ]
        if ignored:
            warnings.warn(
                f"Spider {crawler.spidercls.__name__} defines a different "
                f"value than spider "
                f"{self._reactor_crawler.spidercls.__name__} for the "
                f"following reactor settings: {', '.join(ignored)}. Only "
                f"the value of the first spider is used, since the "
                f"reactor is shared by every spider in a process.",
                stacklevel=2,
            )
    return crawler

def _job_dir(settings: BaseSettings) -> str | None:
    path: str | None = settings["JOBDIR"]
    if not path:
        return None
    if not Path(path).exists():
        Path(path).mkdir(parents=True)
    return path

def start_python_console(
    namespace: dict[str, Any] | None = None,
    banner: str = "",
    shells: Iterable[str] | None = None,
) -> None:
    """Start Python console bound to the given namespace.
    Readline support and tab completion will be used on Unix, if available.
    """
    if namespace is None:
        namespace = {}

    try:
        shell = get_shell_embed_func(shells)
        if shell is not None:
            shell(namespace=namespace, banner=banner)
    except SystemExit:  # raised when using exit() in python code.interact
        pass

def _make_client(self, proxy_url: str | None = None) -> httpx.AsyncClient:
    if proxy_url:
        if proxy_url.startswith("https:") and not self._verify_certificates:
            proxy_ssl_context = _make_insecure_ssl_ctx()
        else:
            proxy_ssl_context = None
        proxy = httpx.Proxy(proxy_url, ssl_context=proxy_ssl_context)
    else:
        proxy = None

    client = httpx.AsyncClient(
        cookies=NullCookieJar(),
        transport=httpx.AsyncHTTPTransport(
            verify=self._ssl_context,
            local_address=self._bind_host,
            http2=self._enable_h2,
            limits=self._limits,
            trust_env=False,
            proxy=proxy,
        ),
    )
    # https://github.com/pydantic/httpx2/issues/368
    for header_name in ("accept", "accept-encoding", "user-agent"):
        client.headers.pop(header_name, None)
    return client

def print_items(self, lvl: int | None = None, colour: bool = True) -> None:
    if lvl is None:
        items = [item for lst in self.items.values() for item in lst]
    else:
        items = self.items.get(lvl, [])

    print("# Scraped Items ", "-" * 60)
    _colorize.pprint([ItemAdapter(x).asdict() for x in items], colorize=colour)

def _export_xml_field(self, name: str, serialized_value: Any, depth: int) -> None:
    self._beautify_indent(depth=depth)
    self.xg.startElement(name, AttributesImpl({}))
    if hasattr(serialized_value, "items"):
        self._beautify_newline()
        for subname, value in serialized_value.items():
            self._export_xml_field(subname, value, depth=depth + 1)
        self._beautify_indent(depth=depth)
    elif is_listlike(serialized_value):
        self._beautify_newline()
        for value in serialized_value:
            self._export_xml_field("value", value, depth=depth + 1)
        self._beautify_indent(depth=depth)
    elif isinstance(serialized_value, str):
        self.xg.characters(serialized_value)
    else:
        self.xg.characters(str(serialized_value))
    self.xg.endElement(name)
    self._beautify_newline()

def binary_is_text(data: bytes) -> bool:
    """Returns ``True`` if the given ``data`` argument (a ``bytes`` object)
    does not contain unprintable control characters.
    """
    if not isinstance(data, bytes):
        raise TypeError(f"data must be bytes, got '{type(data).__name__}'")
    return all(c not in _BINARYCHARS for c in data)

def _extract_links(
    self,
    selector: Selector,
    response_url: str,
    response_encoding: str,
    base_url: str,
) -> list[Link]:
    links: list[Link] = []
    # hacky way to get the underlying lxml parsed document
    for el, _, attr_val in self._iter_links(selector.root):
        # pseudo lxml.html.HtmlElement.make_links_absolute(base_url)
        try:
            if self.strip:
                attr_val = strip_html5_whitespace(attr_val)  # noqa: PLW2901 this is intended
            attr_val = urljoin(base_url, attr_val)  # noqa: PLW2901
        except ValueError:
            continue  # skipping bogus links
        else:
            url = self.process_attr(attr_val)
            if url is None:
                continue
        try:
            url = safe_url_string(url, encoding=response_encoding)
        except ValueError:
            logger.debug(f"Skipping extraction of link with bad URL {url!r}")
            continue

        # to fix relative links after process_value
        url = urljoin(response_url, url)
        link = Link(
            url,
            _collect_string_content(el) or "",
            nofollow=rel_has_nofollow(el.get("rel")),
        )
        links.append(link)
    return self._deduplicate_if_needed(links)

def from_args(
    self,
    headers: Mapping[bytes, bytes] | None = None,
    url: str | None = None,
    filename: str | None = None,
    body: bytes | None = None,
) -> type[Response]:
    """Guess the most appropriate Response class based on
    the given arguments."""
    cls = Response
    if headers is not None:
        cls = self.from_headers(headers)
    if cls is Response and url is not None:
        cls = self.from_filename(url)
    if cls is Response and filename is not None:
        cls = self.from_filename(filename)
    if cls is Response and body is not None:
        cls = self.from_body(body)
    return cls

def process_options(self, args: list[str], opts: argparse.Namespace) -> None:
    """Set settings based on the command line options."""
    assert self.settings is not None
    try:
        self.settings.setdict(arglist_to_dict(opts.set), priority="cmdline")
    except ValueError:
        raise UsageError(
            "Invalid -s value, use -s NAME=VALUE", print_help=False
        ) from None

    if opts.logfile:
        self.settings.set("LOG_ENABLED", True, priority="cmdline")
        self.settings.set("LOG_FILE", opts.logfile, priority="cmdline")

    if opts.loglevel:
        self.settings.set("LOG_ENABLED", True, priority="cmdline")
        self.settings.set("LOG_LEVEL", opts.loglevel, priority="cmdline")

    if opts.nolog:
        self.settings.set("LOG_ENABLED", False, priority="cmdline")

    if opts.pidfile:
        Path(opts.pidfile).write_text(
            str(os.getpid()) + os.linesep, encoding="utf-8"
        )

    if opts.pdb:
        try:
            import ipdb  # noqa: T100,PLC0415
        except ImportError:
            pass
        else:
            sys.modules["pdb"] = ipdb
        logging.root.addHandler(_PdbHandler(level=logging.ERROR))

def __init__(self, obj: Response | str | bytes):
    self._ptr: int = 0
    self._text: str | bytes
    if isinstance(obj, TextResponse):
        self._text, self.encoding = obj.body, obj.encoding
    elif isinstance(obj, Response):
        self._text, self.encoding = obj.body, "utf-8"
    else:
        self._text, self.encoding = obj, "utf-8"
    self._is_unicode: bool = isinstance(self._text, str)
    self._is_first_read: bool = True

def _next_slot(self, stats: list[tuple[int, str]], *, update_state: bool) -> str:
    last = self._last_selected_slot
    min_active: int | None = None
    best_slot: str | None = None
    best_slot_after_last: str | None = None
    for active, slot in stats:
        if min_active is None or active < min_active:
            min_active = active
            best_slot = slot
            best_slot_after_last = None
            if last is not None and slot > last:
                best_slot_after_last = slot
        elif active == min_active:
            if best_slot is None or slot < best_slot:
                best_slot = slot
            if (
                last is not None
                and slot > last
                and (best_slot_after_last is None or slot < best_slot_after_last)
            ):
                best_slot_after_last = slot
    assert best_slot is not None
    slot = best_slot_after_last if best_slot_after_last is not None else best_slot
    if update_state:
        self._last_selected_slot = slot
    return slot

async def download_request(self, request: Request) -> Response:
    if not self.supports_proxies and request.meta.get("proxy"):
        raise NotImplementedError(f"{type(self).__name__} doesn't support proxies.")
    if not self.supports_per_request_bindaddress and request.meta.get(
        "bindaddress"
    ):
        logger.error(
            f"The 'bindaddress' request meta key is not supported by"
            f" {type(self).__name__} and will be ignored."
        )
    timeout: float = request.meta.get(
        "download_timeout", self._DEFAULT_CONNECT_TIMEOUT
    )
    start_time = time.monotonic()
    async with self._make_request(request, timeout) as response:
        request.meta["download_latency"] = time.monotonic() - start_time
        return await self._read_response(response, request)

def push(self, request: Request) -> None:
    priority = self.priority(request)
    is_start_request = request.meta.get("is_start_request", False)
    if is_start_request and self._start_queue_cls:
        if priority not in self._start_queues:
            self._start_queues[priority] = self._sqfactory(priority)
            self.changed = True
        q = self._start_queues[priority]
    else:
        if priority not in self.queues:
            self.queues[priority] = self.qfactory(priority)
            self.changed = True
        q = self.queues[priority]
    q.push(request)  # this may fail (eg. serialization error)
    if self.curprio is None or priority < self.curprio:
        self.curprio = priority

def load_settings(self, settings: Settings) -> None:
    """Load add-ons and configurations from a settings object and apply them.

    This will load the add-on for every add-on path in the
    ``ADDONS`` setting and execute their ``update_settings`` methods.

    :param settings: The :class:`~scrapy.settings.Settings` object from \
        which to read the add-on configuration
    :type settings: :class:`~scrapy.settings.Settings`
    """
    for clspath in build_component_list(settings["ADDONS"]):
        try:
            addoncls = load_object(clspath)
            addon = build_from_crawler(addoncls, self.crawler)
            if hasattr(addon, "update_settings"):
                addon.update_settings(settings)
            self.addons.append(addon)
        except NotConfigured as e:
            if e.args:
                logger.warning(
                    "Disabled %(clspath)s: %(eargs)s",
                    {"clspath": clspath, "eargs": e.args[0]},
                    extra={"crawler": self.crawler},
                )
    logger.info(
        "Enabled addons:\n%(addons)s",
        {
            "addons": self.addons,
        },
        extra={"crawler": self.crawler},

def getlist(
    self, key: str | bytes, def_val: _RawValue | Iterable[_RawValue] | None = None
) -> list[bytes]:
    try:
        return cast("list[bytes]", dict.__getitem__(self, self.normkey(key)))
    except KeyError:
        if def_val is not None:
            return self.normvalue(def_val)
        return []

def _version(item: str) -> str:
    lowercase_item = item.lower()
    if lowercase_item == "libxml2":
        return ".".join(map(str, lxml.etree.LIBXML_VERSION))
    if lowercase_item == "platform":
        return platform.platform()
    if lowercase_item == "pyopenssl":
        return _get_openssl_version()
    if lowercase_item == "python":
        return sys.version.replace("\n", "- ")
    return version(item)

def _warn_if_feeds_unused(self, sender: Crawler, **kwargs: Any) -> None:
    if (
        sender.settings.getdict("FEEDS")
        and sender.get_extension(FeedExporter) is None
    ):
        logger.warning(
            "The FeedExporter extension is not enabled, so no item will be "

def run(self, args: list[str], opts: argparse.Namespace) -> None:
    if opts.verbose:
        versions = get_versions()
        width = max(len(n) for (n, _) in versions)
        for name, version in versions:
            print(f"{name:<{width}} : {version}")
    else:
        print(f"Scrapy {scrapy.__version__}")

def _serialize_value(self, value: Any) -> Any:
    if isinstance(value, Item):
        return self.export_item(value)
    if isinstance(value, (str, bytes)):
        return to_unicode(value, encoding=self.encoding)
    if is_item(value):
        return dict(self._serialize_item(value))
    if is_listlike(value):
        return [self._serialize_value(v) for v in value]
    return value

def iter_spider_classes(module: ModuleType) -> Iterable[type[Spider]]:
    """Return an iterator over all spider classes defined in the given module
    that can be instantiated (i.e. which have name)
    """
    for obj in vars(module).values():
        if (
            inspect.isclass(obj)
            and issubclass(obj, Spider)
            and obj.__module__ == module.__name__
            and getattr(obj, "name", None)
        ):
            yield obj

def data_path(path: str | os.PathLike[str], createdir: bool = False) -> str:
    """
    Return the given path joined with the .scrapy data directory.
    If given an absolute path, return it unmodified.
    """
    path_obj = Path(path)
    if not path_obj.is_absolute():
        if inside_project():
            path_obj = Path(project_data_dir(), path)
        else:
            path_obj = Path(".scrapy", path)
    if createdir and not path_obj.exists():
        path_obj.mkdir(parents=True)
    return str(path_obj)

async def _async_chain(
    *iterables: Iterable[_T] | AsyncIterator[_T],
) -> AsyncIterator[_T]:
    for it in iterables:
        async for o in as_async_generator(it):
            yield o

def failure_to_exc_info(
    failure: Failure,
) -> tuple[type[BaseException], BaseException, TracebackType | None] | None:
    """Extract exc_info from Failure instances"""
    if isinstance(failure, Failure):
        assert failure.type
        assert failure.value
        return (
            failure.type,
            failure.value,
            cast("TracebackType | None", failure.getTracebackObject()),
        )
    return None

def project_data_dir(project: str = "default") -> str:
    """Return the current project data dir, creating it if it doesn't exist"""
    if not inside_project():
        raise NotConfigured("Not inside a project")
    cfg = get_config()
    if cfg.has_option(DATADIR_CFG_SECTION, project):
        d = Path(cfg.get(DATADIR_CFG_SECTION, project))
    else:
        scrapy_cfg = closest_scrapy_cfg()
        if not scrapy_cfg:
            raise NotConfigured(
                "Unable to find scrapy.cfg file to infer project data dir"
            )
        d = (Path(scrapy_cfg).parent / ".scrapy").resolve()
    if not d.exists():
        d.mkdir(parents=True)
    return str(d)

def _callback(self, result: _T) -> None:
    # This gets called when the result from aiterator.__anext__() is available.
    # It calls the callable on it and sends the result to the oldest waiting Deferred
    # (by chaining if the result is a Deferred too or by firing if not).
    self.anext_deferred = None
    self.on_value()
    callable_result = self.callable(
        result, *self.callable_args, **self.callable_kwargs
    )
    d = self.waiting_deferreds.popleft()
    if isinstance(callable_result, Deferred):
        callable_result.chainDeferred(d)
    else:
        d.callback(None)
    if self.waiting_deferreds:
        self._call_anext()

def _add_middleware(self, mw: Any) -> None:
    if hasattr(mw, "process_spider_input"):
        self.methods["process_spider_input"].append(mw.process_spider_input)
        self._check_mw_method_spider_arg(mw.process_spider_input)

    if hasattr(mw, "process_start"):
        self.methods["process_start"].appendleft(mw.process_start)

    process_spider_output = self._get_process_spider_output(mw)
    self.methods["process_spider_output"].appendleft(process_spider_output)
    if process_spider_output is not None:
        self._check_mw_method_spider_arg(process_spider_output)

    process_spider_exception = getattr(mw, "process_spider_exception", None)
    self.methods["process_spider_exception"].appendleft(process_spider_exception)
    if process_spider_exception is not None:
        self._check_mw_method_spider_arg(process_spider_exception)

def get_header_size(
    headers: dict[str, list[str | bytes] | tuple[str | bytes, ...]],
) -> int:
    size = 0
    for key, value in headers.items():
        if isinstance(value, (list, tuple)):
            for v in value:
                size += len(b": ") + len(key) + len(v)
    return size + len(b"\r\n") * (len(headers.keys()) - 1)

def _get_client(self, proxy_url: str | None) -> httpx.AsyncClient:
    if proxy_url is None:
        return self._default_client
    if cached := self._proxy_clients.get(proxy_url):
        return cached
    client = self._make_client(proxy_url)
    self._proxy_clients[proxy_url] = client
    return client

def _make_ssl_context(settings: BaseSettings) -> ssl.SSLContext:
    """Create an :class:`ssl.SSLContext` instance according to the settings.

    It's intended to be used in an HTTPS download handler.
    """

    tls_min_ver, tls_max_ver = _get_tls_version_limits(
        settings, _STDLIB_VERSION_MAP.__getitem__
    )
    ciphers_setting: str | None = settings["DOWNLOADER_CLIENT_TLS_CIPHERS"]
    verify_setting = settings.getbool("DOWNLOAD_VERIFY_CERTIFICATES")

    ctx = ssl.SSLContext(ssl.PROTOCOL_TLS_CLIENT)
    if verify_setting:
        ctx.check_hostname = True
        ctx.verify_mode = ssl.CERT_REQUIRED
        ctx.load_default_certs()
    else:
        ctx.check_hostname = False
        ctx.verify_mode = ssl.CERT_NONE
    if tls_min_ver is not None:
        ctx.minimum_version = tls_min_ver
    if tls_max_ver is not None:
        ctx.maximum_version = tls_max_ver
    if ciphers_setting:
        ctx.set_ciphers(ciphers_setting)
    if keylog_filename := _get_keylog_filename():
        ctx.keylog_filename = keylog_filename
    return ctx

def getdictorlist(
    self,
    name: str,
    default: dict[Any, Any] | list[Any] | tuple[Any, ...] | None = None,
) -> dict[Any, Any] | list[Any]:
    """Get a setting value as either a :class:`dict` or a :class:`list`.

    If the setting is already a dict or a list, a copy of it will be
    returned.

    If it is a string it will be evaluated as JSON, or as a comma-separated
    list of strings as a fallback.

    For example, settings populated from the command line will return:

    -   ``{'key1': 'value1', 'key2': 'value2'}`` if set to
        ``'{"key1": "value1", "key2": "value2"}'``

    -   ``['one', 'two']`` if set to ``'["one", "two"]'`` or ``'one,two'``

    :param name: the setting name
    :type name: str

    :param default: the value to return if no setting is found
    :type default: object
    """
    value = self.get(name, default)
    if value is None:
        return {}
    if isinstance(value, str):
        try:
            value_loaded = json.loads(value)
            if not isinstance(value_loaded, (dict, list)):
                raise ValueError(
                    f"JSON string for setting '{name}' must evaluate to a dict or list, "
                    f"got {type(value_loaded).__name__}: {value_loaded!r}"
                )
            return value_loaded
        except ValueError:
            return value.split(",")
    if isinstance(value, tuple):
        return list(value)
    if not isinstance(value, (dict, list)):
        raise ValueError(
            f"Setting '{name}' must be a dict, list, tuple, or string, "
            f"got {type(value).__name__}: {value!r}"
        )
    return copy.deepcopy(value)

def pop(self, name: str, default: Any = __default) -> Any:  # pylint: disable=arguments-renamed
    try:
        value = self.attributes[name].value
    except KeyError:
        if default is self.__default:
            raise
        return default
    del self[name]
    return value

def page_count(self, response: Response, request: Request, spider: Spider) -> None:
    self.counter["pagecount"] += 1
    self.counter["pagecount_since_last_item"] += 1
    if self.counter["pagecount"] == self.close_on["pagecount"]:
        self._close_spider("closespider_pagecount")
        return
    if self.close_on["pagecount_no_item"] and (
        self.counter["pagecount_since_last_item"]
        >= self.close_on["pagecount_no_item"]
    ):
        self._close_spider("closespider_pagecount_no_item")

async def _wait_for_download(
    self, slot: Slot, request: Request, queue_dfd: Deferred[Response]
) -> None:
    try:
        response = await self._download(slot, request)
    except Exception:
        if not queue_dfd.called:
            queue_dfd.errback(Failure())
    else:
        queue_dfd.callback(response)  # awaited in _enqueue_request()

def _get_form(
    response: TextResponse,
    formname: str | None,
    formid: str | None,
    formnumber: int,
    formxpath: str | None,
) -> FormElement:
    """Find the wanted form element within the given response."""
    root = response.selector.root
    forms = root.xpath("//form")
    if not forms:
        raise ValueError(f"No <form> element found in {response}")

    if formname is not None:
        f = root.xpath(f'//form[@name="{formname}"]')
        if f:
            return cast("FormElement", f[0])

    if formid is not None:
        f = root.xpath(f'//form[@id="{formid}"]')
        if f:
            return cast("FormElement", f[0])

    # Get form element from xpath, if not found, go up
    if formxpath is not None:
        nodes = root.xpath(formxpath)
        if nodes:
            el = nodes[0]
            while True:
                if el.tag == "form":
                    return cast("FormElement", el)
                el = el.getparent()
                if el is None:
                    break
        raise ValueError(f"No <form> element found with {formxpath}")

    # If we get here, it means that either formname was None or invalid
    try:
        form = forms[formnumber]
    except IndexError:
        raise IndexError(f"Form number {formnumber} not found in {response}") from None
    return cast("FormElement", form)

def _pop_command_name(argv: list[str]) -> str | None:
    for i in range(1, len(argv)):
        if not argv[i].startswith("-"):
            return argv.pop(i)
    return None

def _handle_events(self, events: list[Event]) -> None:
    """Private method which acts as a bridge between the events
    received from the HTTP/2 data and the handlers in this class.

    Arguments:
        events -- A list of events that the remote peer triggered by sending data
    """
    for event in events:
        if isinstance(event, ConnectionTerminated):
            self.connection_terminated(event)
        elif isinstance(event, DataReceived):
            self.data_received(event)
        elif isinstance(event, ResponseReceived):
            self.response_received(event)
        elif isinstance(event, StreamEnded):
            self.stream_ended(event)
        elif isinstance(event, StreamReset):
            self.stream_reset(event)
        elif isinstance(event, WindowUpdated):
            self.window_updated(event)
        elif isinstance(event, SettingsAcknowledged):
            self.settings_acknowledged(event)
        elif isinstance(event, UnknownFrameReceived):
            logger.warning("Unknown frame received: %s", event.frame)

def _process_spider_exception(
    self,
    response: Response,
    exception: Exception,
    start_index: int = 0,
) -> MutableAsyncChain[_T]:
    # don't handle _InvalidOutput exception
    if isinstance(exception, _InvalidOutput):
        raise exception
    method_list = islice(
        self.methods["process_spider_exception"], start_index, None
    )
    for method_index, method in enumerate(method_list, start=start_index):
        if method is None:
            continue
        if method in self._mw_methods_requiring_spider:
            result = method(
                response=response, exception=exception, spider=self._spider
            )
        else:
            result = method(response=response, exception=exception)
        if isinstance(result, (Iterable, AsyncIterator)):
            # stop exception handling by handing control over to the
            # process_spider_output chain if an iterable has been returned
            if isinstance(result, Iterable):
                result = as_async_generator(result)
            return self._process_spider_output(response, result, method_index + 1)
        if result is None:
            continue
        msg = (
            f"{global_object_name(method)} must return None "
            f"or an iterable, got {type(result)}"
        )
        raise _InvalidOutput(msg)
    # Every remaining middleware declined to handle the exception, so the
    # outer process_spider_output layers must let it through instead of
    # offering it to those middlewares again.
    with suppress(AttributeError):
        exception._spidermw_unhandled = True  # type: ignore[attr-defined]
    raise exception

def ensure_awaitable(o: _T | Awaitable[_T], _warn: str | None = None) -> Awaitable[_T]:
    """Convert any value to an awaitable object.

    For a :class:`~twisted.internet.defer.Deferred` object, use
    :func:`maybe_deferred_to_future` to wrap it into a suitable object. For an
    awaitable object of a different type, return it as is. For any other
    value, return a coroutine that completes with that value.

    .. versionadded:: 2.14
    """
    if isinstance(o, Deferred):
        if _warn:
            warnings.warn(
                f"{_warn} returned a Deferred, this is deprecated."
                f" Please refactor this function to return a coroutine.",
                ScrapyDeprecationWarning,
                stacklevel=2,
            )
        return maybe_deferred_to_future(o)
    if inspect.isawaitable(o):
        return o

    async def coro() -> _T:
        return o

    return coro()

def __init__(self, contracts: Iterable[type[Contract]]):
    for contract in contracts:
        if (
            contract.add_pre_hook is not Contract.add_pre_hook
            or contract.add_post_hook is not Contract.add_post_hook
        ):
            warnings.warn(
                f"{contract.__module__}.{contract.__qualname__} overrides"
                " Contract.add_pre_hook() or Contract.add_post_hook(), which is"
                " deprecated. Define pre_process() or post_process() instead."
                " Contracts that override those methods do not support"
                " asynchronous callbacks.",
                ScrapyDeprecationWarning,
                stacklevel=2,
            )
        self.contracts[contract.name] = contract

def __setitem__(self, key: _KT, value: _VT) -> None:
    if self.limit is not None:
        if self.limit == 0:
            return
        if key not in self:
            while len(self) >= self.limit:
                self.popitem(last=False)
    super().__setitem__(key, value)

def __get__(
    self, instance: Crawler | None, owner: type[Crawler]
) -> _LateAttribute[_T] | _T:
    if instance is None:
        return self
    value: _T | None = getattr(instance, self._private_name)
    if value is None:
        raise RuntimeError(
            f"Crawler.{self._name} is not set yet. It is set when the "
            "crawl starts, so it can only be used from then on, e.g. "
            "from the spider_opened signal handler onwards."
        )
    return value

def resolveHostName(
    self,
    resolutionReceiver: IResolutionReceiver,
    hostName: str,
    portNumber: int = 0,
    addressTypes: Sequence[type[IAddress]] | None = None,
    transportSemantics: str = "TCP",
) -> IHostResolution:
    try:
        addresses = dnscache[hostName]
    except KeyError:
        return self.original_resolver.resolveHostName(
            _CachingResolutionReceiver(resolutionReceiver, hostName),
            hostName,
            portNumber,
            addressTypes,
            transportSemantics,
        )
    resolutionReceiver.resolutionBegan(HostResolution(hostName))
    for address in addresses:
        resolutionReceiver.addressResolved(_address_with_port(address, portNumber))
    resolutionReceiver.resolutionComplete()
    return resolutionReceiver

def item_completed(
    self, results: list[FileInfoOrError], item: Any, info: SpiderInfo
) -> Any:
    """Called per item when all media requests has been processed"""
    if self.LOG_FAILED_RESULTS:
        for ok, value in results:
            if not ok:
                assert isinstance(value, Failure)
                if _media_request_filtered(value):
                    continue
                logger.error(
                    "%(class)s found errors processing %(item)s",
                    {"class": self.__class__.__name__, "item": item},
                    exc_info=failure_to_exc_info(value),
                    extra={"spider": info.spider},
                )
    return item

def _report_crawl_errors(
    crawl: Awaitable[None], spidername: str, result: TextTestResult
) -> None:
    """Make an exception that stops *crawl* before its contracts can run show
    up as an error in *result*, instead of being silently discarded."""

    class CrawlTestCase(TestCase):
        # unittest requires a test method, but this one is only reported, never run.
        runTest = staticmethod(lambda: None)

        def __str__(self) -> str:
            return f"[{spidername}] crawl"

    def report(exception: BaseException) -> None:
        result.addError(
            CrawlTestCase(),
            (type(exception), exception, exception.__traceback__),  # type: ignore[arg-type]
        )

    if isinstance(crawl, Deferred):

        def on_failure(failure: Failure) -> None:
            assert failure.value is not None
            report(failure.value)

        crawl.addErrback(on_failure)
    else:
        assert isinstance(crawl, asyncio.Task)

        def on_done(task: asyncio.Task[None]) -> None:
            if not task.cancelled() and (exception := task.exception()) is not None:
                report(exception)

        crawl.add_done_callback(on_done)

def _clean_req(
    self, request: Request, method: Callable[..., Any], results: TestResult
) -> None:
    """stop the request from returning objects and records any errors"""

    cb = request.callback
    assert cb is not None

    if _is_async(cb):

        @wraps(cb)
        async def cb_wrapper(response: Response, **cb_kwargs: Any) -> None:
            try:
                await _collect_async(cb(response, **cb_kwargs))
            except Exception:
                case = _create_testcase(method, "callback")
                results.addError(case, sys.exc_info())

    else:

        @wraps(cb)
        def cb_wrapper(response: Response, **cb_kwargs: Any) -> None:
            try:
                _collect(cb(response, **cb_kwargs))
            except Exception:
                case = _create_testcase(method, "callback")
                results.addError(case, sys.exc_info())

    def eb_wrapper(failure: Failure) -> None:
        case = _create_testcase(method, "errback")
        exc_info = failure.type, failure.value, failure.getTracebackObject()
        results.addError(case, exc_info)  # type: ignore[arg-type]

    request.callback = cb_wrapper
    request.errback = eb_wrapper

def _get_handler(self, scheme: str) -> DownloadHandlerProtocol | None:
    """Lazy-load the downloadhandler for a scheme
    only on the first request for that scheme.
    """
    if scheme in self._handlers:
        return self._handlers[scheme]
    if scheme in self._notconfigured:
        return None
    if scheme not in self._schemes:
        self._notconfigured[scheme] = "no handler available for that scheme"
        return None

    return self._load_handler(scheme)

def _get_tag_name(elem: lxml.etree._Element) -> str:
    tag = elem.tag
    if not isinstance(tag, str):
        return ""
    _, _, localname = tag.partition("}")
    return localname or tag

def __init__(self, *args: Any, **kwargs: Any):
    super().__init__(*args, **kwargs)

    if len(self.args) not in {1, 2, 3}:
        raise ValueError(
            f"Incorrect argument quantity: expected 1, 2 or 3, got {len(self.args)}"
        )
    self.obj_name = self.args[0] or None
    self.obj_type_verifier = self.object_type_verifiers[self.obj_name]

    try:
        self.min_bound: float = int(self.args[1])
    except IndexError:
        self.min_bound = 1

    try:
        self.max_bound: float = int(self.args[2])
    except IndexError:
        self.max_bound = float("inf")

def open(self, spider: Spider) -> IO[bytes]:
    dirname = Path(self.path).parent
    if dirname and not dirname.exists():
        dirname.mkdir(parents=True)
    return Path(self.path).open(self.write_mode)

async def download_request_async(self, request: Request) -> Response:
    scheme = urlparse_cached(request).scheme
    handler = self._get_handler(scheme)
    if not handler:
        raise NotSupported(
            f"Unsupported URL scheme '{scheme}': {self._notconfigured[scheme]}"
        )
    assert self._crawler.spider
    if scheme in self._old_style_handlers:  # pragma: no cover
        return await maybe_deferred_to_future(
            cast(
                "Deferred[Response]",
                handler.download_request(request, self._crawler.spider),  # type: ignore[call-arg]
            )
        )
    return await handler.download_request(request)

def _freshen_cached_response(
    self, cachedresponse: Response, response: Response
) -> None:
    # RFC 7234, section 4.3.4: update the stored response with the
    # header fields from a successful revalidation (304) response.
    warnings = [
        warning
        for warning in cachedresponse.headers.getlist(b"Warning")
        if warning.split(None, 1)[0].startswith(b"2")
    ]
    cachedresponse.headers.update(response.headers)
    if warnings:
        cachedresponse.headers[b"Warning"] = warnings
    else:
        cachedresponse.headers.pop(b"Warning", None)

def process_response(
    self, request: Request, response: Response, spider: Spider | None = None
) -> Request | Response:
    if (
        request.meta.get("dont_redirect", False)
        or response.status
        in getattr(self.crawler.spider, "handle_httpstatus_list", ())
        or response.status in request.meta.get("handle_httpstatus_list", ())
        or request.meta.get("handle_httpstatus_all", False)
    ):
        return response

    if "Location" not in response.headers or response.status not in {
        301,
        302,
        303,
        307,
        308,
    }:
        return response

    assert response.headers["Location"] is not None
    location = safe_url_string(response.headers["Location"])
    if response.headers["Location"].startswith(b"//"):
        request_scheme = urlparse_cached(request).scheme
        location = request_scheme + "://" + location.lstrip("/")

    redirected_url = urljoin(request.url, location)

    if not urlparse(redirected_url).fragment:
        fragment = urlparse_cached(request).fragment
        if fragment:
            redirected_url = urljoin(redirected_url, f"#{fragment}")

    redirected = self._build_redirect_request(request, response, url=redirected_url)
    if urlparse_cached(redirected).scheme not in {"http", "https"}:
        return response

    if (response.status in {301, 302} and request.method == "POST") or (
        response.status == 303 and request.method not in {"GET", "HEAD"}
    ):
        redirected = self._redirect_request_using_get(
            request, response, redirected_url
        )

    return self._redirect(redirected, request, response.status)

async def _process_response(
    self, response: Response | Request, request: Request, index: int = 0
) -> Response | Request:
    if response is None:
        raise TypeError("Received None in process_response")

    methods = self.methods["process_response"]
    while index < len(methods):
        if isinstance(response, Request):
            return response
        method = methods[index]
        index += 1
        if method is None:
            continue
        try:
            result = await ensure_awaitable(
                self._handle_mw_method(method, request=request, response=response),
                _warn=global_object_name(method),
            )
        except Exception as ex:
            if not self._response_exceptions:
                # CloseSpider closes the spider either way, it never
                # reaches process_exception().
                if not isinstance(ex, CloseSpider):
                    self._warn_response_exception(method, ex, index)
                raise
            response, index = await self._process_exception(ex, request, index)
            continue

        if not isinstance(result, (Response, Request)):
            raise _InvalidOutput(
                f"Middleware {method.__qualname__} must return Response or Request, "
                f"got {type(result)}"
            )
        response = result
    return response

def from_headers(self, headers: Mapping[bytes, bytes]) -> type[Response]:
    """Return the most appropriate Response class by looking at the HTTP
    headers"""
    cls = Response
    if b"Content-Type" in headers:
        cls = self.from_content_type(
            content_type=headers[b"Content-Type"],
            content_encoding=headers.get(b"Content-Encoding"),
        )
    if cls is Response and b"Content-Disposition" in headers:
        cls = self.from_content_disposition(headers[b"Content-Disposition"])
    return cls

def creatorForNetloc(self, hostname: bytes, port: int) -> ClientTLSOptions:
    if not self._verify_certificates:
        # Our options class is needed to skip verification errors
        if TWISTED_TLS_NEW_IMPL:
            return _ScrapyClientTLSOptions26(
                self._get_cert_options()._makeTLSConnection,
                hostname.decode("ascii"),
            )
        return _ScrapyClientTLSOptions(
            hostname.decode("ascii"),  # type: ignore[arg-type]
            self._get_context(),  # type: ignore[arg-type]
        )
    # Otherwise use the normal Twisted function.
    creator = optionsForClientTLS(
        hostname=hostname.decode("ascii"),
        extraCertificateOptions=self._get_cert_options_kwargs(),
    )
    if _get_keylog_filename():
        # This creator builds its own certificate options, so its context
        # doesn't come from _ScrapyCertificateOptions.
        _set_keylog_callback(_get_creator_context(creator))
    return cast("ClientTLSOptions", creator)

def _install_twisted_idna_fallbacks() -> None:
    """Patch ``_idnaBytes()``/``_idnaText()`` wherever Twisted uses them for
    client connections.

    Each module binds them at import time, so every reference needs patching,
    not just ``twisted.internet._idna``. Names that are missing or already
    patched are left alone.
    """
    from twisted.internet import _resolver, _sslverify, endpoints  # noqa: PLC0415

    patches = (
        ("_idnaBytes", _original_idna_bytes, _patched_idna_bytes),
        ("_idnaText", _original_idna_text, _patched_idna_text),
    )
    for module in (_idna, _resolver, _sslverify, endpoints):
        for name, original, patched in patches:
            if getattr(module, name, None) is original:
                setattr(module, name, patched)

def _set_body(self, body: bytes | None) -> None:
    if body is None:
        self._body = b""
    elif not isinstance(body, bytes):
        raise TypeError(
            "Response body must be bytes. "
            "If you want to pass unicode body use TextResponse "
            "or HtmlResponse."
        )
    else:
        self._body = body

def iterate_spider_output(
    result: Any,
) -> Iterable[Any] | AsyncGenerator[_T] | Deferred[_T]:
    if inspect.isasyncgen(result):
        return cast("AsyncGenerator[_T]", result)
    d: Deferred[_T] = deferred_from_coro(result)
    if inspect.iscoroutine(result):
        return d.addCallback(iterate_spider_output)
    return arg_to_iter(d)

def _compute_current_age(
    self, response: Response, request: Request, now: float
) -> float:
    # Reference nsHttpResponseHead::ComputeCurrentAge
    # https://dxr.mozilla.org/mozilla-central/source/netwerk/protocol/http/nsHttpResponseHead.cpp#658
    currentage: float = 0
    # If Date header is not set we assume it is a fast connection, and
    # clock is in sync with the server
    date = rfc1123_to_epoch(response.headers.get(b"Date")) or now
    if now > date:
        currentage = now - date

    if b"Age" in response.headers:
        try:
            age = int(response.headers[b"Age"])  # type: ignore[arg-type]
            currentage = max(currentage, age)
        except ValueError:
            pass

    return currentage

def _sitemap_urls_from_robots_str(
    robots_text: str,
    base_url: str | None = None,
) -> Iterable[str]:
    for line in StringIO(robots_text):
        if line.lstrip()[:8].lower() == "sitemap:":
            url = line.partition(":")[2].strip()
            yield urljoin(base_url or "", url)

def post_process(self, output: list[Any]) -> None:
    occurrences = 0
    for x in output:
        if self.obj_type_verifier(x):
            occurrences += 1

    assertion = self.min_bound <= occurrences <= self.max_bound

    if not assertion:
        if self.min_bound == self.max_bound:
            expected = str(self.min_bound)
        else:
            expected = f"{self.min_bound}..{self.max_bound}"

        raise ContractFail(
            f"Returned {occurrences} {self.obj_name}, expected {expected}"

def get_serialized_fields(
    self, item: Any, default_value: Any = None, include_empty: bool | None = None
) -> Iterable[tuple[str, Any]]:
    """Return the fields of *item* to export, as an iterable of
    ``(name, serialized_value)`` tuples, taking :attr:`fields_to_export`
    into account and applying :meth:`serialize_field` to every value.

    Fields missing from *item* are exported with *default_value*.

    *include_empty* overrides :attr:`export_empty_fields`.
    """
    item = ItemAdapter(item)

    if include_empty is None:
        include_empty = self.export_empty_fields

    if self.fields_to_export is None:
        field_iter = (
            item.field_names()
            if include_empty
            else self._get_populated_field_names(item)
        )
    elif isinstance(self.fields_to_export, Mapping):
        if include_empty:
            field_iter = self.fields_to_export.items()
        else:
            field_iter = (
                (x, y) for x, y in self.fields_to_export.items() if x in item
            )
    elif include_empty:
        field_iter = self.fields_to_export
    else:
        field_iter = (x for x in self.fields_to_export if x in item)

    for field_name in field_iter:
        if isinstance(field_name, str):
            item_field, output_field = field_name, field_name
        else:
            item_field, output_field = field_name
        if item_field in item:
            field_meta = item.get_field_meta(item_field)
            value = self.serialize_field(field_meta, output_field, item[item_field])
        else:
            value = default_value

        yield output_field, value

def get_func_args_dict(
    func: Callable[..., Any], stripself: bool = False
) -> Mapping[str, inspect.Parameter]:
    """Return the argument dict of a callable object.

    Annotations are not evaluated, so on Python 3.14 and later the ``annotation``
    attribute of the returned parameters may be a ``ForwardRef`` instead of the
    resolved type.

    .. versionadded:: 2.14
    """
    if not callable(func):
        raise TypeError(f"func must be callable, got '{type(func).__name__}'")

    args: Mapping[str, inspect.Parameter]
    try:
        sig = _signature(func)
    except ValueError:
        return {}

    if isinstance(func, partial) and func.keywords:
        # The signature of a partial already omits the parameters bound to
        # positional arguments, but it keeps those bound to keyword arguments,
        # turned into keyword-only parameters with a default.
        args = {
            name: param
            for name, param in sig.parameters.items()
            if name not in func.keywords
        }
    else:
        args = sig.parameters

    if stripself and args and "self" in args:
        args = {k: v for k, v in args.items() if k != "self"}
    return args

def get_processed_request(
    self, request: Request, response: Response | None
) -> Request | None:
    if response is None:
        return request

    if not self._warned:
        found = self._keys & request.meta.keys()
        if found:
            spider_name = type(self.crawler.spider).__name__
            logger.warning(
                f"{spider_name} yielded a request containing internal "
                f"meta keys that were likely copied from response.meta "
                f"and should not be forwarded to new requests: "
                f"{sorted(found)}. See the MetaCopyDetectionMiddleware "
                f"documentation for more information. Source response: "
                f"{response}, target request: {request}",
                extra={"spider": self.crawler.spider},
            )
            self._warned = True

    return request

def format_live_refs(
    ignore: type[Any] | tuple[type[Any], ...] = NoneType,
) -> str:
    """Return a tabular representation of tracked objects"""
    s = "Live References\n\n"
    now_ns = monotonic_ns()
    for cls, wdict in sorted(live_refs.items(), key=lambda x: x[0].__name__):
        if not wdict:
            continue
        if issubclass(cls, ignore):
            continue
        oldest_ns = min(wdict.values())
        s += f"{cls.__name__:<30} {len(wdict):6}   oldest: {int((now_ns - oldest_ns) // 1e9)}s ago\n"
    return s

def scraped(
    self, item: Any, response: Response | Failure | None, spider: Spider
) -> LogFormatterResult:
    """Logs a message when an item is scraped by a spider."""
    src: Any
    if response is None:
        src = f"{global_object_name(spider.__class__)}.start"
    elif isinstance(response, Failure):
        src = response.getErrorMessage()
    else:
        src = response
    return {
        "level": logging.DEBUG,
        "msg": SCRAPEDMSG,
        "args": {
            "src": src,
            "item": item,

def get_oldest(class_name: str) -> Any:
    """Return the oldest object alive with the given class name, or ``None`` if
    none is found. Use :func:`print_live_refs` first to get a list of all
    tracked live objects per class name."""
    for cls, wdict in live_refs.items():
        if cls.__name__ == class_name:
            if not wdict:
                break
            return min(wdict.items(), key=itemgetter(1))[0]
    return None

def add_post_hook(self, request: Request, results: TestResult) -> Request:
    if hasattr(self, "post_process"):
        cb = request.callback
        assert cb is not None
        post_process = self.post_process
        testcase = self.testcase_post

        if _is_async(cb):

            @wraps(cb)
            async def async_wrapper(
                response: Response, **cb_kwargs: Any
            ) -> list[Any]:
                output = await _collect_async(cb(response, **cb_kwargs))
                _run_hook(post_process, output, testcase, results)
                return output

            request.callback = async_wrapper
        else:

            @wraps(cb)
            def wrapper(response: Response, **cb_kwargs: Any) -> list[Any]:
                output = _collect(cb(response, **cb_kwargs))
                _run_hook(post_process, output, testcase, results)
                return output

            request.callback = wrapper

    return request

def get_sources(use_closest: bool = True) -> list[str]:
    xdg_config_home = (
        os.environ.get("XDG_CONFIG_HOME") or Path("~/.config").expanduser()
    )
    sources = [
        "/etc/scrapy.cfg",
        r"c:\scrapy\scrapy.cfg",
        str(Path(xdg_config_home) / "scrapy.cfg"),
        str(Path("~/.scrapy.cfg").expanduser()),
    ]
    if use_closest:
        sources.append(closest_scrapy_cfg())
    return sources

def execute(argv: list[str] | None = None, settings: Settings | None = None) -> None:
    if argv is None:
        argv = sys.argv

    if settings is None:
        settings = get_project_settings()
        # set EDITOR from environment if available
        try:
            editor = os.environ["EDITOR"]
        except KeyError:
            pass
        else:
            settings["EDITOR"] = editor

    inproject = inside_project()
    cmds = _get_commands_dict(settings, inproject)
    cmdname = _pop_command_name(argv)
    if not cmdname:
        _print_commands(settings, inproject)
        sys.exit(0)
    elif cmdname not in cmds:
        _print_unknown_command(settings, cmdname, inproject)
        sys.exit(2)

    cmd = cmds[cmdname]
    parser = ScrapyArgumentParser(
        formatter_class=ScrapyHelpFormatter,
        usage=f"scrapy {cmdname} {cmd.syntax()}",
        conflict_handler="resolve",
        description=cmd.long_desc(),
    )
    settings.setdict(cmd.default_settings, priority="command")
    cmd.settings = settings
    cmd.add_options(parser)
    opts, args = parser.parse_known_args(args=argv[1:])
    _run_print_help(parser, cmd.process_options, args, opts)

    if cmd.requires_crawler_process:
        if (
            settings["TWISTED_REACTOR"] == _asyncio_reactor_path
            and not settings.getbool("FORCE_CRAWLER_PROCESS")
        ) or not settings.getbool("TWISTED_REACTOR_ENABLED"):
            cmd.crawler_process = AsyncCrawlerProcess(settings)
        else:
            cmd.crawler_process = CrawlerProcess(settings)
    _run_print_help(parser, _run_command, cmd, args, opts)
    sys.exit(cmd.exitcode)

def iterate_spider_output(self, result: Any) -> Iterable[Any] | Deferred[Any]:
    d: Deferred[Any]
    if inspect.isasyncgen(result):
        d = deferred_from_coro(
            collect_asyncgen(aiter_errback(result, self.handle_exception))
        )
        return d.addCallback(self.iterate_spider_output)
    d = deferred_from_coro(result)
    if inspect.iscoroutine(result):
        return d.addCallback(self.iterate_spider_output)
    return arg_to_iter(d)

def headers(
    self,
    value: Mapping[str, Any]
    | Mapping[bytes, Any]
    | Iterable[tuple[str | bytes, Any]]
    | None,
) -> None:
    if isinstance(value, Headers):
        self._headers = value
    else:
        self._headers = (
            Headers(value, encoding=self.encoding) if value is not None else None

def ftp_makedirs_cwd(ftp: FTP, path: str, first_call: bool = True) -> None:
    """Set the current directory of the FTP connection given in the ``ftp``
    argument (as a ftplib.FTP object), creating all parent directories if they
    don't exist. The ftplib.FTP object must be already connected and logged in.
    """
    try:
        ftp.cwd(path)
    except error_perm:
        ftp_makedirs_cwd(ftp, dirname(path), False)
        ftp.mkd(path)
        if first_call:
            ftp.cwd(path)

def run(self, args: list[str], opts: argparse.Namespace) -> None:
    # parse arguments
    if not len(args) == 1 or not is_url(args[0]):
        raise UsageError
    url = args[0]

    # prepare spidercls
    self.set_spidercls(url, opts)

    if self.spidercls and opts.depth > 0:
        self.start_parsing(url, opts)
        self.print_results(opts)

def _write_headers_and_set_fields_to_export(self, item: Any) -> None:
    if self.include_headers_line:
        if not self.fields_to_export:
            # use declared field names, or keys if the item is a dict
            self.fields_to_export = ItemAdapter(item).field_names()
            self._autodetected_fields = True
        fields: Iterable[str]
        if isinstance(self.fields_to_export, Mapping):
            fields = self.fields_to_export.values()
        else:
            assert self.fields_to_export
            fields = self.fields_to_export
        row = list(self._build_row(fields))
        self.csv_writer.writerow(row)

def _declared_encoding(self) -> str | None:
    return (
        self._encoding
        or self._bom_encoding()
        or self._headers_encoding()
        or self._body_declared_encoding()

def request_from_dict(d: dict[str, Any], *, spider: Spider | None = None) -> Request:
    """Create a :class:`~scrapy.Request` object from a dict.

    If a spider is given, it will try to resolve the callbacks looking at the
    spider for methods with the same name.
    """
    request_cls: type[Request] = load_object(d["_class"]) if "_class" in d else Request
    kwargs = {key: value for key, value in d.items() if key in request_cls.attributes}
    if d.get("callback") and spider:
        kwargs["callback"] = _get_method(spider, d["callback"])
    if d.get("errback") and spider:
        kwargs["errback"] = _get_method(spider, d["errback"])
    return request_cls(**kwargs)

def __len__(self) -> int:
    return (
        sum(
            len(x)
            for queues in (self.queues, self._start_queues)
            for x in queues.values()
        )
        if self.queues or self._start_queues
        else 0

def _run_print_help(
    parser: argparse.ArgumentParser,
    func: Callable[_P, None],
    *a: _P.args,
    **kw: _P.kwargs,
) -> None:
    try:
        func(*a, **kw)
    except UsageError as e:
        if str(e):
            parser.error(str(e))
        if e.print_help:
            parser.print_help()
        sys.exit(2)

def get_versions(
    software: list[str] | None = None,
) -> list[tuple[str, str]]:
    software = software or _DEFAULT_SOFTWARE
    return [(item, _version(item)) for item in software]

def iter_errback(
    iterable: Iterable[_T],
    errback: Callable[Concatenate[Failure, _P], Any],
    *a: _P.args,
    **kw: _P.kwargs,
) -> Iterable[_T]:
    """Wrap an iterable calling an errback if an error is caught while
    iterating it.
    """
    it = iter(iterable)
    while True:
        try:
            yield next(it)
        except StopIteration:
            break
        except Exception:
            errback(failure.Failure(), *a, **kw)

def _debug_set_cookie(self, response: Response) -> None:
    if self.debug:
        cl = [
            to_unicode(c, errors="replace")
            for c in response.headers.getlist("Set-Cookie")
        ]
        if cl:
            cookies = "\n".join(f"Set-Cookie: {c}\n" for c in cl)
            msg = f"Received cookies from: {response}\n{cookies}"
            logger.debug(msg, extra={"spider": self.crawler.spider})

async def close_spider(self, spider: Spider) -> None:
    for slot in self.slots:
        self._schedule_slot_close(slot, spider)

    if self._pending_close_tasks:  # pragma: no branch
        if is_asyncio_available():
            await asyncio.wait(
                cast("list[asyncio.Task[None]]", list(self._pending_close_tasks))
            )
        else:
            await DeferredList(
                cast("list[Deferred[None]]", list(self._pending_close_tasks))
            )

    # Send FEED_EXPORTER_CLOSED signal
    await self.crawler.signals.send_catch_log_async(signals.feed_exporter_closed)

def _select_value(
    ele: SelectElement, n: str | None, v: str | MultipleSelectOptions | None
) -> tuple[str | None, str | MultipleSelectOptions | None]:
    multiple = ele.multiple
    if v is None and not multiple:
        # Match browser behaviour on simple select tag without options selected
        # And for select tags without options
        o = ele.value_options
        return (n, o[0]) if o else (None, None)
    return n, v

def header_items(self) -> list[tuple[str, list[str]]]:
    return [
        (
            to_unicode(k, errors="replace"),
            [to_unicode(x, errors="replace") for x in v],
        )
        for k, v in self.request.headers.items()

def _get_commands_from_entry_points(
    inproject: bool, group: str = "scrapy.commands"
) -> dict[str, ScrapyCommand]:
    cmds: dict[str, ScrapyCommand] = {}
    for entry_point in entry_points(group=group):
        obj = entry_point.load()
        if inspect.isclass(obj) and issubclass(obj, ScrapyCommand):
            cmds[entry_point.name] = obj()
        else:
            raise ValueError(f"Invalid entry point {entry_point.name}")
    return cmds

def __init__(self, name: str | None = None, **kwargs: Any):
    if name is not None:
        self.name: str = name
    elif not getattr(self, "name", None):
        raise ValueError(f"{type(self).__name__} must have a name")
    self.__dict__.update(kwargs)
    if not hasattr(self, "start_urls"):
        self.start_urls: list[str] = []
